(5, 'salle', 'Propose une bouteille de vin avec un accord à 2 tables', true),
(6, 'salle', 'Accueille chaque table de ta zone en moins de 30 secondes toute la semaine', true),
(7, 'bar', 'Présente la Mixology Class à 3 clients', true),
(8, 'bar', 'Raconte l''origine d''un cocktail classique à 3 clients', true),
(9, 'bar', 'Zéro préparation maison sans étiquette au bar toute la semaine', true),
