insert into daraja.questions (id, venue, theme, question, options, answer_idx, explanation, active, level, kind, payload, cat) values
('08a2f5e0-441b-5b14-91c9-e055fdddc50b', null, 'Actualité du Maroc', 'Quel pays a accueilli la Coupe d''Afrique des nations 2025 ?', '["Le Maroc", "L''Égypte", "La Côte d''Ivoire", "Le Sénégal"]', 0, 'Le Maroc, de décembre 2025 à janvier 2026. La finale s''est jouée à Rabat le 18 janvier 2026.', true, 1, 'qcm', null, 'agenda'),
('248bf2e1-2446-55c4-a204-9e7bc82148ed', null, 'Agenda de Marrakech', 'Le festival Gnaoua d''Essaouira a lieu en hiver.', '["Vrai", "Faux"]', 1, 'Faux : il a lieu en général fin juin, quand la ville est fraîche grâce aux alizés.', true, 1, 'tf', null, 'agenda'),
('2aaaca36-6c8e-5795-b5de-fac03606cc92', null, 'Actualité du Maroc', 'Combien de touristes le Maroc a-t-il accueillis en 2025, un record ?', '["Environ 2 millions", "Environ 19,8 millions", "Environ 50 millions", "Environ 100 millions"]', 1, 'Environ 19,8 millions, 14 % de plus qu''en 2024 : un record historique pour le pays.', true, 1, 'qcm', null, 'agenda'),
('434261a6-497c-54a1-8964-967caedb8ef2', null, 'Agenda de Marrakech', 'À quelle période a lieu le Festival international du film de Marrakech ?', '["En janvier", "Fin novembre", "En plein mois d''août", "À Pâques"]', 1, 'Chaque fin d''automne : stars, projections et tapis rouge au palais des congrès.', true, 1, 'qcm', null, 'agenda'),
('4c43269f-07fa-574c-9392-840942cd8ab4', null, 'Actualité du Maroc', 'Marrakech fait partie des villes hôtes de la Coupe du monde 2030.', '["Vrai", "Faux"]', 0, 'Vrai : le Grand Stade de Marrakech accueillera des matchs. Une belle saison en perspective pour l''hôtellerie et la restauration !', true, 1, 'tf', null, 'agenda'),
('6756a778-2e7e-5e8d-93db-e53e9d62b870', null, 'Agenda de Marrakech', 'Quel humoriste a créé le festival « Marrakech du rire » ?', '["Jamel Debbouze", "Kev Adams", "Gad Elmaleh", "Omar Sy et Fred"]', 0, 'Jamel Debbouze. Le festival, au palais El Badi, révèle aussi de jeunes humoristes.', true, 1, 'qcm', null, 'agenda'),
('8aac3f77-4bc0-59ec-a392-b4f5db662ef7', null, 'Actualité du Maroc', 'Avec quels pays le Maroc organisera-t-il la Coupe du monde 2030 ?', '["L''Espagne et le Portugal", "L''Algérie et la Tunisie", "La France et l''Italie", "L''Égypte et l''Arabie saoudite"]', 0, 'Avec l''Espagne et le Portugal. Trois matchs auront aussi lieu en Amérique du Sud pour fêter les 100 ans de la compétition.', true, 1, 'qcm', null, 'agenda'),
('eb59e6be-2e7d-5fd7-9143-ef74f039c9d0', null, 'Raconte l''actualité', '« Il se passe quoi à Marrakech ce week-end ? »', '["« Rien, c''est calme ce week-end. »", "« Je regarde l''agenda et je vous note tout. »", "« Le festival Gnaoua, comme chaque semaine. »", "« Demandez à Google, c''est plus simple. »"]', 1, 'Avoir l''agenda en tête, ou savoir le trouver vite, fait de toi un vrai conseiller. Vérifie toujours les dates du moment.', true, 1, 'scene', null, 'agenda'),
('f22ba59c-260d-5fa4-9e4a-c4f16c3ebcd7', null, 'Agenda de Marrakech', 'En quel mois se court le marathon international de Marrakech ?', '["En juillet", "En août", "En septembre", "Fin janvier"]', 3, 'Fin janvier, quand il fait frais : une tradition depuis 1987.', true, 1, 'qcm', null, 'agenda'),
('3006e588-6ace-5dee-9a76-f79b079d64c4', null, 'Actualité du Maroc', 'Comment s''appelle le TGV marocain ?', '["Al Boraq", "L''Atlas Express", "Le Shinkansen", "L''Eurostar"]', 0, 'Al Boraq, en service entre Tanger et Kénitra depuis 2018 : le premier TGV d''Afrique. Il doit rejoindre Marrakech.', true, 2, 'qcm', null, 'agenda'),
('6a89d0d3-1f6a-5893-97e3-5240195d1ed3', null, 'Agenda de Marrakech', 'Qui préside le jury du Festival du film de Marrakech 2026 ?', '["Jamel Debbouze", "Omar Sy", "Martin Scorsese", "Marion Cotillard"]', 3, 'L''actrice française Marion Cotillard, oscarisée pour « La Môme ».', true, 2, 'qcm', null, 'agenda'),
('7a6048c0-8c87-5727-b9dc-e2627f70d469', null, 'Raconte l''actualité', '« Il y a beaucoup de touristes cette année, non ? »', '["« Oui, près de 50 millions en 2025, un record. »", "« Non, c''est moins que l''an dernier. »", "« Oui, surtout à cause de la CAN cet été. »", "« Oui, près de 20 millions en 2025, un record. »"]', 3, 'Transformer une remarque en fierté et en remerciement : c''est l''esprit d''accueil.', true, 2, 'scene', null, 'agenda'),
('7ca66e44-fd5d-56c0-b024-cb363ff2a73a', null, 'Actualité du Maroc', 'Pourquoi trois matchs de la Coupe du monde 2030 se joueront-ils en Amérique du Sud ?', '["Par tirage au sort", "Les stades ne seront pas prêts", "À cause du climat", "Pour le centenaire de 1930"]', 3, 'La première Coupe du monde s''est jouée en Uruguay en 1930. Uruguay, Argentine et Paraguay accueilleront chacun un match d''ouverture.', true, 2, 'qcm', null, 'agenda'),
('8007441b-a151-5ae2-92da-039951cf104b', null, 'Agenda de Marrakech', 'Quelles sont les dates du Festival international du film de Marrakech 2026 ?', '["Du 24 au 31 décembre 2026", "Du 20 au 28 novembre 2026", "Du 1er au 7 juillet 2026", "Du 10 au 15 mars 2026"]', 1, 'Du 20 au 28 novembre 2026, pour la 23e édition : 76 films de 39 pays.', true, 2, 'qcm', null, 'agenda'),
('9f65d218-08d3-5539-93ed-755e783c27b4', null, 'Agenda de Marrakech', 'Dans quelle ville se tient le grand festival de musique Mawazine ?', '["Rabat", "Chefchaouen", "Ouarzazate", "Marrakech"]', 0, 'Rabat : des stars internationales et marocaines, en plein air, chaque printemps ou début d''été.', true, 2, 'qcm', null, 'agenda'),
('aedae282-3920-5f3a-a4d2-634bde76fca2', null, 'Agenda de Marrakech', 'Dans quelle ville a lieu le festival des musiques sacrées du monde ?', '["Tétouan", "Laâyoune", "Agadir", "Fès"]', 3, 'Fès, depuis 1994 : des musiques spirituelles du monde entier dans des lieux historiques.', true, 2, 'qcm', null, 'agenda'),
('bbffe0ab-f692-5287-a76b-4ce0b14c2c3b', null, 'Actualité du Maroc', 'Jusqu''où le Maroc est-il allé à la Coupe du monde 2022 au Qatar ?', '["Il n''était pas qualifié", "En finale, avec la victoire", "Éliminé au premier tour", "En demi-finale"]', 3, 'Demi-finale, battu par la France : une épopée historique pour les Lions de l''Atlas.', true, 2, 'qcm', null, 'agenda'),
('c93bcfae-1f47-56b1-95d1-13ae5f9e0e41', null, 'Raconte l''actualité', '« On revient en 2030 pour la Coupe du monde, vous nous conseillez quoi ? »', '["« Les matchs seront tous à Casablanca. »", "« La finale est déjà prévue ici, à Marrakech. »", "« Pas besoin de réserver, il y a de la place. »", "« Réservez tôt : Marrakech sera ville hôte. »"]', 3, 'Se projeter avec le client crée un lien… et peut-être une future réservation.', true, 2, 'scene', null, 'agenda'),
('cf36e50f-42d4-5d03-ada9-9165f3c40ce4', null, 'Actualité du Maroc', 'Quelle capacité est prévue pour le Grand Stade Hassan II, en construction à Benslimane ?', '["Environ 250 000 places", "Environ 40 000 places", "Environ 15 000 places", "Environ 115 000 places"]', 3, 'Environ 115 000 places : l''un des plus grands stades du monde, inspiré d''une tente de moussem.', true, 2, 'qcm', null, 'agenda'),
('e1852e3f-7926-57cc-a475-f5c75d483294', null, 'Agenda de Marrakech', 'Quel événement réunit chaque mois de février l''art contemporain africain à Marrakech ?', '["Le festival Gnaoua", "Le salon de l''auto", "La foire 1-54", "Le Marrakech du rire"]', 2, 'La foire 1-54, fondée par Touria El Glaoui : elle se tient aussi à Londres et à New York. En 2026, du 5 au 8 février.', true, 2, 'qcm', null, 'agenda'),
('ebac3c3d-204a-57d3-b724-9715a636abce', null, 'Actualité du Maroc', 'Quel temps de trajet Rabat - Marrakech est annoncé avec la future ligne à grande vitesse ?', '["Environ 6 heures", "Environ 1 h 40", "Environ 4 heures", "Environ 20 minutes"]', 1, 'Environ 1 h 40, contre plus de 3 heures aujourd''hui. Mise en service visée en 2029, avant le Mondial.', true, 2, 'qcm', null, 'agenda'),
('743f3e98-2156-526e-9f52-a4d1d56bf070', null, 'Agenda de Marrakech', 'Comment s''appelle le grand prix du Festival du film de Marrakech ?', '["La Palme d''or", "L''Ours d''or", "L''Étoile d''or", "Le Lion d''or"]', 2, 'L''Étoile d''or. La Palme, c''est Cannes ; l''Ours, Berlin ; le Lion, Venise.', true, 3, 'qcm', null, 'agenda'),
('2b234e47-4efc-4d83-8bb1-5c488d792b50', null, 'English', 'Propose ton cocktail signature en anglais', '[]', 0, 'La formule polie par excellence : « May I… ».', true, 1, 'order', '{"answer": ["May", "I", "recommend", "our", "signature", "cocktail", "?"]}', 'anglais'),
('2cb6259a-3b93-47c9-afd1-57fa55e981d0', null, 'Anglais en images', 'En anglais, une crevette se dit…', '["A prawn (ou shrimp)", "A crab", "A lobster", "A squid"]', 0, 'Prawn ou shrimp = crevette. Lobster = homard.', true, 1, 'image', '{"img": "ef1f8ff69f82"}', 'anglais'),
('3fdae597-0e62-4101-8082-a55c3dca4b6a', null, 'English', '« L''addition, s''il vous plaît » : le client anglais dit…', '["The count, please", "The note, please", "The bill, please", "The addition, please"]', 2, '« Bill » en Angleterre, « check » aux États-Unis.', true, 1, 'qcm', null, 'anglais'),
('429b0a41-c4ff-4190-8e61-5164ffb5e4d1', null, 'Anglais en images', 'En anglais, ce fruit se dit…', '["Cherry", "Raspberry", "Blueberry", "Strawberry"]', 3, 'Strawberry = fraise. Raspberry = framboise.', true, 1, 'image', '{"img": "410e9867b280"}', 'anglais'),
('43c54f52-d15e-43e2-b5bb-e5536f713a5c', null, 'Anglais en images', 'En anglais, ce fruit se dit…', '["Lemon", "Orange", "Grapefruit", "Lime"]', 0, 'Lemon = citron jaune. Lime = citron vert.', true, 1, 'image', '{"img": "1192b8967623"}', 'anglais'),
('608eee6a-b91f-4c94-a165-fabc60648124', null, 'Anglais en images', 'En anglais, ça se dit…', '["Garlic", "Leek", "Ginger", "Onion"]', 0, 'Garlic = ail. Onion = oignon. Leek = poireau.', true, 1, 'image', '{"img": "f668c306a2bd"}', 'anglais'),
('6aa9d281-0b45-4fbe-bb5b-95b03449c99f', null, 'Anglais en images', 'En anglais, ce fruit se dit…', '["Avocado", "Lawyer", "Pear", "Olive"]', 0, 'Avocado ! « Lawyer », c''est l''avocat… au tribunal.', true, 1, 'image', '{"img": "f948be2c0d8e"}', 'anglais'),
('8eaba602-432c-4f22-b047-a651d4cf5f46', null, 'English', 'Comment dire « Bon appétit » à un client anglophone ?', '["Have a good food", "Enjoy your meal", "Good appetite", "Eat well"]', 1, '« Enjoy your meal » est la formule naturelle.', true, 1, 'qcm', null, 'anglais'),
('a450fc55-eed2-493d-ae9c-cbfd88b3615d', null, 'English', 'Demande les allergies', '[]', 0, 'Une question à poser à chaque table, en anglais comme en français.', true, 1, 'order', '{"answer": ["Do", "you", "have", "any", "food", "allergies", "?"]}', 'anglais'),
('d4bd6ca2-16e7-48ef-89b9-844a5162a7e5', null, 'English', '« Je reviens tout de suite » se dit…', '["I''m coming back soon", "I come back now", "I''ll be right back", "I return quickly"]', 2, 'Court, poli, naturel.', true, 1, 'qcm', null, 'anglais'),
('d785ba34-39f2-4377-9659-1e6e3cefb4a0', null, 'English', '« Prenez votre temps » en anglais :', '["Have your time", "Take your time", "Make your time", "Take the time"]', 1, '« Take your time, I''ll come back in a minute. »', true, 1, 'qcm', null, 'anglais'),
('dcff21d0-8016-4f06-8d5b-608e369d845b', null, 'English', 'Propose l''eau', '[]', 0, 'Still = plate, sparkling = pétillante.', true, 1, 'order', '{"answer": ["Would", "you", "like", "still", "or", "sparkling", "water", "?"]}', 'anglais'),
('e6cb9288-e580-46e8-8fe2-baf33dd40671', null, 'Anglais en images', 'Un client demande « Is it spicy? ». Il veut savoir si c''est…', '["Cher", "Froid", "Sucré", "Épicé, pimenté"]', 3, 'Spicy = épicé. Tu peux répondre : « Just a little » ou « Not at all ».', true, 1, 'image', '{"img": "d9964e08be09"}', 'anglais'),
('ff8075b8-cff7-47e1-a6c0-b10973d3e93b', null, 'Associations', 'Relie le français à l''anglais', '[]', 0, 'Les mots qu''on entend tous les soirs.', true, 1, 'match', '{"pairs": [["Agneau", "Lamb"], ["Poulpe", "Octopus"], ["Loup bar", "Sea bass"], ["Gambas", "Prawns"]]}', 'anglais'),
('0294a61b-0c0a-449f-a898-e77154609c9e', null, 'English', 'Quelle phrase est correcte ?', '["I''m agree", "I am agree with you", "I agree with you", "I agreed with you now"]', 2, 'Erreur très fréquente : on ne dit jamais « I am agree ».', true, 2, 'qcm', null, 'anglais'),
('31948391-82d7-44fd-82a9-72c7d4f656c3', null, 'Anglais en images', 'En anglais, le calamar se dit…', '["Octopus", "Shrimp", "Oyster", "Squid"]', 3, 'Squid = calamar. Octopus = poulpe.', true, 2, 'image', '{"img": "ca691820e935"}', 'anglais'),
('43101bde-c7e6-404b-9d3d-72bf5269301e', null, 'English', 'Propose le dessert', '[]', 0, 'Le moment idéal : quand tu débarrasses les assiettes.', true, 2, 'order', '{"answer": ["Would", "you", "like", "to", "see", "the", "dessert", "menu", "?"]}', 'anglais'),
('608d3fb1-a5a6-4308-a843-e16d357f0b15', null, 'English', 'Annonce l''attente de la table', '[]', 0, 'Un délai honnête rassure le client.', true, 2, 'order', '{"answer": ["Your", "table", "will", "be", "ready", "in", "five", "minutes", "."]}', 'anglais'),
('7ccc72b7-5306-43df-84bc-7bdb1b4b4042', null, 'English', '« Loup bar » en anglais :', '["Bar fish", "Sea bream", "Sea bass", "Sea wolf"]', 2, 'Sea bass. La daurade, elle, se dit sea bream.', true, 2, 'qcm', null, 'anglais'),
('8174f026-fd18-455c-9470-7cba5dd83c75', null, 'English', '« Effiloché de bœuf » en anglais :', '["Pulled cow", "Shredded cow", "Torn beef", "Pulled beef"]', 3, '« Pulled » : comme le célèbre pulled pork.', true, 2, 'qcm', null, 'anglais'),
('c2fd6667-2aed-4d69-8b22-62ef618916ed', null, 'English', '« Citron confit » en anglais :', '["Pickled orange", "Confit lemon", "Candied lemon", "Preserved lemon"]', 3, 'Preserved lemon : un classique de la cuisine marocaine.', true, 2, 'qcm', null, 'anglais'),
('daacd920-acae-4a91-9e9e-3a7b2c8fe16d', null, 'English', 'Propose une autre tournée', '[]', 0, '« Round » = une tournée pour toute la table.', true, 2, 'order', '{"answer": ["Can", "I", "get", "you", "another", "round", "?"]}', 'anglais'),
('f0ef7962-2431-433f-a302-a67da1e4478c', null, 'Associations', 'Relie chaque formule polie à sa traduction', '[]', 0, 'La politesse, la base.', true, 2, 'match', '{"pairs": [["Prenez votre temps", "Take your time"], ["Je reviens tout de suite", "I''ll be right back"], ["Santé !", "Cheers!"], ["Bon appétit", "Enjoy your meal"]]}', 'anglais'),
('41d41410-80df-4866-9e28-c1d2208b4b2c', null, 'English', 'Le client demande « Is the octopus grilled? ». Il parle du…', '["Gambas", "Calamar", "Poisson du jour", "Poulpe"]', 3, 'Octopus = poulpe, squid = calamar, prawns = gambas.', true, 3, 'qcm', null, 'anglais'),
('868d6384-086e-47d8-ac39-90bc13a8102d', null, 'English', '« Cèpes » en anglais :', '["Truffles", "Morels", "Porcini mushrooms", "Button mushrooms"]', 2, 'Le nom italien porcini est utilisé en anglais.', true, 3, 'qcm', null, 'anglais'),
('e06075e4-0aea-478d-b6e7-a7305b1d539f', null, 'English', 'Dis au revoir comme un pro', '[]', 0, 'Chaleureux et simple.', true, 3, 'order', '{"answer": ["Thank", "you", "for", "coming", ",", "we", "hope", "to", "see", "you", "again", "soon", "!"]}', 'anglais'),
('eca05879-b4fb-4711-9247-b07aeae64f42', null, 'English', 'Demande un avis Google avec élégance', '[]', 0, 'Une demande douce, jamais insistante.', true, 3, 'order', '{"answer": ["If", "you", "enjoyed", "your", "evening", ",", "a", "Google", "review", "would", "mean", "a", "lot", "to", "us", "."]}', 'anglais'),
('011c61d2-93ca-5aff-a65f-bd36c0923cba', null, 'Art de vivre', 'À quoi sert la kessa au hammam ?', '["À gommer la peau", "À chauffer l''eau", "À payer l''entrée", "À se sécher les cheveux"]', 0, 'Le gant de gommage : après le savon noir, il enlève les peaux mortes. La peau ressort toute douce.', true, 1, 'qcm', null, 'artisanat'),
('3eadb4cc-2b6c-56cc-ad57-99825444b512', null, 'Artisanat', 'Que sont les babouches ?', '["Des chapeaux en laine", "Des chaussons en cuir", "Des bijoux berbères", "Des plats en terre"]', 1, 'Des chaussons en cuir, souvent jaunes pour les hommes et brodés pour les femmes. On les trouve dans tous les souks.', true, 1, 'qcm', null, 'artisanat'),
('4fb057e1-ac2c-5b6f-9fa1-f9db2c14126a', null, 'Artisanat', 'Avec quelle matière tisse-t-on les tapis Beni Ouarain ?', '["Le plastique", "La laine de mouton", "La soie de Chine", "Le coton américain"]', 1, 'La laine des moutons du Moyen Atlas : des tapis épais, souvent écrus à motifs de losanges sombres.', true, 1, 'qcm', null, 'artisanat'),
('7f7ab599-ae24-5841-872a-c58db3dbec4f', null, 'Art de vivre', 'Avec quoi se lave-t-on traditionnellement au hammam avant le gommage ?', '["Le savon noir (savon beldi)", "Le sable", "Le shampoing anti-pelliculaire", "Le lait"]', 0, 'Le savon noir, à base d''huile d''olive : on le laisse poser pour ramollir la peau.', true, 1, 'qcm', null, 'artisanat'),
('85a8d799-85ae-56a5-a124-905ebf0a91b8', null, 'Patrimoine UNESCO', 'Quel vêtement marocain est entré au patrimoine immatériel de l''UNESCO en décembre 2025 ?', '["Le jean", "Le caftan", "Le smoking", "Le kilt"]', 1, 'Le caftan marocain : arts, traditions et savoir-faire. Une fierté nationale, inscrite à New Delhi.', true, 1, 'qcm', null, 'artisanat'),
('8aa0673c-1c08-52f3-89d5-3d3d3b6b85ce', null, 'Artisanat', 'Comment appelle-t-on le long vêtement à capuche porté au Maroc ?', '["Le sari", "Le kimono", "La djellaba", "Le poncho"]', 2, 'La djellaba, portée par les hommes et les femmes, au quotidien comme les jours de fête.', true, 1, 'qcm', null, 'artisanat'),
('ac38b878-ab7c-5610-a554-69a69f857c22', null, 'Art de vivre', 'Que sert-on traditionnellement à un invité qui arrive, en signe de bienvenue ?', '["Un soda", "Du thé à la menthe", "Du café froid", "Rien, il faut attendre"]', 1, 'Le thé à la menthe : le refuser serait presque vexant. Lors des grandes fêtes, on accueille aussi avec des dattes et du lait.', true, 1, 'qcm', null, 'artisanat'),
('c9535214-b19d-5035-878f-cff8d833aa7f', null, 'Raconte l''artisanat', '« Où est-ce que je peux acheter un bel objet artisanal sans me faire avoir ? »', '["« Au souk, le premier prix est le bon. »", "« Sur Internet, c''est moins cher. »", "« À l''Ensemble artisanal, à prix fixes. »", "« À l''aéroport, juste avant de partir. »"]', 2, 'Une adresse fiable et un conseil malin : le client se sent protégé et bien guidé.', true, 1, 'scene', null, 'artisanat'),
('fd43351b-685c-505b-aa73-4cfa9eb9f866', null, 'Artisanat', 'Au souk, chaque objet artisanal est unique car il est fait à la main.', '["Vrai", "Faux"]', 0, 'Vrai pour l''artisanat véritable : de petites différences prouvent le travail de l''artisan.', true, 1, 'tf', null, 'artisanat'),
('03fa4d5c-1c0a-50f7-b656-76912e6a81dd', null, 'Art de vivre', 'Que veut dire « Marhaba » ?', '["Bienvenue", "Au revoir", "Merci", "Bon appétit"]', 0, 'Bienvenue. Avec « Bslama » (au revoir) et « Shukran » (merci), les premiers mots que les clients adorent apprendre.', true, 2, 'qcm', null, 'artisanat'),
('0aa9be0c-bd9e-5040-9438-118184b7d92d', null, 'Artisanat', 'Quel produit naturel teint le cuir des babouches en jaune ?', '["Le charbon", "Le café", "L''indigo", "Le safran"]', 3, 'Le safran, selon les tanneurs de Fès. Le rouge vient des roses, le brun du bois de cèdre.', true, 2, 'qcm', null, 'artisanat'),
('46e9ee6c-5cef-5d0f-89a5-bb302db093e2', null, 'Patrimoine UNESCO', 'Quelle pratique de beauté et de fête a été inscrite à l''UNESCO en 2024, notamment par le Maroc ?', '["Le henné", "La coloration blonde", "Le tatouage moderne", "Le maquillage permanent"]', 0, 'Le henné : rituels, esthétique et pratiques sociales, un dossier porté par plusieurs pays arabes.', true, 2, 'qcm', null, 'artisanat'),
('60fa0861-adff-56b7-80cf-75b6a78b4475', null, 'Art de vivre', 'Pourquoi mange-t-on traditionnellement avec la main droite ?', '["Pour ne pas se brûler", "Parce que c''est plus rapide", "Par tradition et politesse", "Parce que la gauche est faible"]', 2, 'C''est une règle de politesse : on se sert avec la main droite, dans la partie du plat devant soi.', true, 2, 'qcm', null, 'artisanat'),
('726f6dd8-ab94-5780-9650-3258e1d3ce64', null, 'Artisanat', 'Qu''est-ce que la dinanderie ?', '["La broderie sur soie", "L''art de la danse", "Le travail du cuivre", "La cuisine des dîners"]', 2, 'Plateaux, théières, lanternes… martelés et ciselés à la main par les dinandiers.', true, 2, 'qcm', null, 'artisanat'),
('7a8f6382-73fb-5665-b76a-714b800c874e', null, 'Raconte l''artisanat', '« On a vu des dessins au henné sur des mains, ça veut dire quoi ? »', '["« Un tatouage permanent, fait à l''aiguille. »", "« Une protection contre le soleil. »", "« Une mode récente venue d''Inde. »", "« Une tradition de fête, inscrite à l''UNESCO. »"]', 3, 'Une explication respectueuse et précise ouvre une belle conversation sur la culture.', true, 2, 'scene', null, 'artisanat'),
('7d1b9832-1f96-5202-88f5-dae26e15a4f9', null, 'Artisanat', 'Quel bois parfumé travaille-t-on en marqueterie à Essaouira ?', '["L''acajou", "Le thuya", "Le bambou", "Le chêne"]', 1, 'Le thuya, surtout ses loupes de racines : chaque pièce a des veines uniques et sent le cèdre et l''encens.', true, 2, 'qcm', null, 'artisanat'),
('7dfbf91e-3dd5-5419-b00a-d955c9cdc5a4', null, 'Artisanat', 'Qu''est-ce qu''un tapis boucherouite ?', '["Un tapis en soie royale", "Un tapis en tissus recyclés", "Un tapis de prière en cuir", "Un tapis volant de légende"]', 1, 'Un tapis coloré fait de vieux vêtements découpés en bandes : la récup'' version berbère.', true, 2, 'qcm', null, 'artisanat'),
('7fac4014-2640-587b-94f0-ee65e1bcd6aa', null, 'Raconte l''artisanat', '« C''est quoi, cette odeur de bois dans la boîte qu''on m''a offerte ? »', '["« Du cèdre de l''Atlas, verni à l''huile. »", "« Du santal, importé d''Inde. »", "« Un parfum ajouté par l''artisan. »", "« Du thuya, un bois d''Essaouira. »"]', 3, 'Nommer la matière et son origine valorise le cadeau… et l''artisan.', true, 2, 'scene', null, 'artisanat'),
('853d5192-dd1e-554b-83aa-d40949197a66', null, 'Artisanat', 'Quelle ville côtière est réputée pour sa colline des potiers ?', '["Safi", "Ouarzazate", "Ifrane", "Merzouga"]', 0, 'Safi : des générations de potiers y travaillent l''argile, avec leurs fours sur la colline.', true, 2, 'qcm', null, 'artisanat'),
('929d158e-b8f0-52d7-8ca9-7c8120fbfa1f', null, 'Patrimoine UNESCO', 'Qu''est-ce que la Tbourida, inscrite à l''UNESCO en 2021 ?', '["Une danse de salon", "Un jeu de cartes ancien", "Une soupe de fèves", "Une fantasia à cheval"]', 3, 'Une troupe de cavaliers galope en ligne et tire au même instant : un seul coup de feu doit retentir.', true, 2, 'qcm', null, 'artisanat'),
('9560b855-4898-5fea-bcea-de1bb41f298d', null, 'Art de vivre', 'Lors d''un mariage marocain, quelle cérémonie a lieu le plus souvent la veille ?', '["La remise des diplômes", "Le défilé militaire", "La soirée du henné", "Le méchoui du lendemain"]', 2, 'La soirée du henné : on dessine des motifs sur les mains et les pieds de la mariée, au milieu des chants.', true, 2, 'qcm', null, 'artisanat'),
('999a6945-d827-5d4b-87a7-ee160e431404', null, 'Art de vivre', 'Qu''est-ce que le ghassoul ?', '["Un instrument de musique", "Une épice très piquante", "Une argile pour se laver", "Une pâtisserie au miel"]', 2, 'Une argile de l''Atlas, mélangée à l''eau ou à l''eau de rose : masque et shampoing traditionnels.', true, 2, 'qcm', null, 'artisanat'),
('9ed25fd7-783a-58fb-806d-969409323dc5', null, 'Artisanat', 'Quelle ville abrite la célèbre tannerie Chouara, avec ses cuves de couleurs ?', '["Dakhla", "Agadir", "Tanger", "Fès"]', 3, 'Fès. La tannerie travaille le cuir à la main depuis des siècles, dans des dizaines de cuves de pierre.', true, 2, 'qcm', null, 'artisanat'),
('bfa85ac2-3d40-5ecc-943a-7c0370f9e6ef', null, 'Artisanat', 'Quelle couleur fait la renommée de la poterie de Fès ?', '["Le doré", "Le noir", "Le bleu", "Le vert fluo"]', 2, 'Le bleu de Fès, sur fond blanc : une signature reconnaissable entre toutes.', true, 2, 'qcm', null, 'artisanat'),
('3811d23b-daf1-5b6b-9efd-e62313bddfff', null, 'Patrimoine UNESCO', 'Qu''est-ce que la Taskiwin, inscrite à l''UNESCO en 2017 ?', '["Un festival de cinéma", "Un tapis de Fès", "Une recette de pain", "Une danse martiale"]', 3, 'Une danse guerrière où les danseurs portent une corne décorée. Elle est sur la liste de sauvegarde urgente.', true, 3, 'qcm', null, 'artisanat'),
('5273fb97-b881-5fe1-8885-a4496231ae1e', null, 'Artisanat', 'Avec quoi assouplit-on traditionnellement les peaux dans les tanneries de Fès ?', '["Du lait de chamelle caillé", "De l''huile d''argan chaude", "De l''eau de mer salée", "De la chaux et de la fiente"]', 3, 'Chaux et fiente de pigeon, jusqu''à deux semaines : d''où l''odeur… et le brin de menthe qu''on offre aux visiteurs.', true, 3, 'qcm', null, 'artisanat'),
('b6322cb0-1a42-53b4-9be2-9a656fe6f045', null, 'Raconte l''artisanat', '« Votre lanterne est magnifique, elle vient d''où ? »', '["« Elle vient d''un grand magasin de déco. »", "« Faite main par les dinandiers de la médina. »", "« Elle est importée d''Égypte, comme souvent. »", "« Elle est moulée en usine à Casablanca. »"]', 1, 'Connaître l''histoire du décor du lieu, c''est prolonger l''expérience du client. Vérifie l''origine réelle auprès de ton responsable.', true, 3, 'scene', null, 'artisanat'),
('d4a83382-8b60-513b-8dd7-af65b9621949', null, 'Patrimoine UNESCO', 'Qu''est-ce que le Malhoun, inscrit à l''UNESCO en 2023 ?', '["Un plat de fête", "Une poésie chantée", "Un sport de combat", "Une façon de tisser"]', 1, 'Une poésie populaire chantée en darija, accompagnée de musique, née dans les villes impériales.', true, 3, 'qcm', null, 'artisanat'),
('e456443a-c844-59b4-9006-fa0974d374f6', null, 'Patrimoine UNESCO', 'Quel art du métal a été inscrit à l''UNESCO en 2023, avec le Maroc parmi les pays porteurs ?', '["La fonte de l''acier", "Le chromage industriel", "La soudure à l''arc", "La gravure sur métaux"]', 3, 'La gravure sur métaux : bijoux, plateaux et lanternes ciselés à la main.', true, 3, 'qcm', null, 'artisanat'),
('f9a5cda8-4ed3-59c1-8e62-c72507073f81', null, 'Patrimoine UNESCO', 'Combien d''éléments marocains figurent au patrimoine immatériel de l''UNESCO fin 2025 ?', '["1", "16", "100", "3"]', 1, 'Seize, de la place Jemaa el-Fna (2008) au caftan (2025), en passant par l''argan, les Gnaoua et le couscous.', true, 3, 'qcm', null, 'artisanat'),
('0e0a420e-82c2-4cf1-84fb-586a47a92464', null, 'Caisse', 'Chaque produit servi doit avoir un bon ou un ticket enregistré.', '["Vrai", "Faux"]', 0, 'Vrai ! Un produit servi sans ticket est une faute dans la charte.', true, 1, 'tf', null, 'caisse'),
('17b25d69-9b61-4959-9fd0-1a0f729e0e5b', null, 'Caisse', 'Comment rendre la monnaie ?', '["En comptant devant le client", "En arrondissant à mon avantage", "Sans la compter", "En la posant vite sur la table"]', 0, 'Compter devant le client évite les litiges.', true, 1, 'qcm', null, 'caisse'),
('9ce0fb5d-6554-4db8-9293-c5209e634809', null, 'Stock', 'La règle FIFO à la réserve, c''est…', '["Premier entré, premier sorti", "Le plus cher sort d''abord", "Au hasard, selon la place", "Le plus récent sort d''abord"]', 0, 'On place les nouveaux produits derrière les anciens.', true, 1, 'qcm', null, 'caisse'),
('a710ed67-be36-4121-a32b-a5cc72435f81', null, 'Caisse en images', 'Un client demande l''addition. Tu remets…', '["Le ticket d''une autre table", "Rien, tu annonces le total", "Un papier écrit à la main", "Le ticket édité par la caisse"]', 3, 'Chaque produit servi doit passer en caisse et figurer sur le ticket.', true, 1, 'image', '{"img": "a6d12ba0ad63"}', 'caisse'),
('ee125808-aa33-4656-8ff7-ef1f71daecbd', null, 'Caisse en images', 'Paiement par carte : le client…', '["Donne son code au serveur", "Laisse sa carte au bar", "Signe un papier vierge", "Garde sa carte en vue et tape son code seul"]', 3, 'Le code est secret : on tourne le terminal vers le client.', true, 1, 'image', '{"img": "57c1aeeda712"}', 'caisse'),
('f95b1fa1-02e8-450e-8298-83409f318a3c', null, 'Caisse', 'Il manque de l''argent dans ta caisse en fin de service. Tu…', '["Le caches jusqu''à demain matin", "Modifies le ticket pour équilibrer", "Le signales tout de suite au responsable", "Complètes de ta poche sans rien dire"]', 2, 'Un écart signalé se comprend. Un écart caché devient une faute grave.', true, 1, 'qcm', null, 'caisse'),
('1a497887-e4b2-4d61-b2ef-a2706488aa31', null, 'Caisse', 'Qui peut annuler un ticket déjà encaissé ?', '["Le responsable, après validation", "Le client, s''il le demande poliment", "Personne, rien n''est vérifié", "N''importe quel serveur de la salle"]', 0, 'Une annulation sans validation est une faute grave.', true, 2, 'qcm', null, 'caisse'),
('53c93166-5479-4ff5-b126-5cde8fa43337', null, 'Achats', 'Tu ramènes du poisson frais du marché. Comment le transportes-tu ?', '["Peu importe, c''est court", "En glacière, direct au froid", "Dans un sac, au soleil", "Dans le coffre, toute la journée"]', 1, 'La chaîne du froid commence dès l''achat.', true, 2, 'qcm', null, 'caisse'),
('6d77722d-6421-4b94-94de-fa4131f967cc', null, 'Stock', 'À la réception d''une livraison, avant de signer, tu vérifies…', '["Quantités, prix, dates, état", "Seulement le nombre de cartons", "Uniquement la facture", "Rien, le livreur est pressé"]', 0, 'Une fois signé, il est trop tard pour réclamer.', true, 2, 'qcm', null, 'caisse'),
('b429103a-9fb4-4d4c-bb1b-2506465b745a', null, 'Caisse', 'Un billet te paraît suspect. Tu…', '["Le déchires devant lui, sans un mot", "L''acceptes pour ne pas le vexer", "Vérifies et préviens le responsable", "Accuses le client de fraude"]', 2, 'On reste courtois : le client peut être de bonne foi.', true, 2, 'qcm', null, 'caisse'),
('c19e7bcf-bd24-46d8-86da-6d629ca5d4d9', null, 'Achats', 'Quand tu fais un achat pour l''établissement, tu rapportes toujours…', '["Juste la monnaie et le sac", "Rien, on te fait confiance", "La facture au nom de la société", "Une photo du magasin et des prix"]', 2, 'Sans pièce justificative, la dépense ne peut pas être comptabilisée.', true, 2, 'qcm', null, 'caisse'),
('511170ca-5367-47b8-ac14-9d88001423ef', null, 'Caisse', 'Le « Z » de caisse, c''est…', '["Une remise client", "Le code de la caisse", "Un ticket annulé", "Le rapport de clôture"]', 3, 'Il sert à contrôler les recettes chaque soir.', true, 3, 'qcm', null, 'caisse'),
('76b78306-8696-41aa-bbb4-6b0ff7f25e31', null, 'Stock', 'Un cocktail coûte 25 DH en ingrédients et se vend 125 DH. Son coût matière est de…', '["50 %", "25 %", "80 %", "20 %"]', 3, '25 ÷ 125 = 0,20, soit 20 %.', true, 3, 'qcm', null, 'caisse'),
('ec050d28-c83c-43ce-b109-5f86cf1b9d6e', null, 'Stock', 'À quoi sert l''inventaire ?', '["Repérer les écarts de stock", "Ranger toute la réserve", "Commander au hasard", "Compter les clients du mois"]', 0, 'Un écart révèle une perte, une casse ou une erreur de saisie.', true, 3, 'qcm', null, 'caisse'),
('20f7706c-ea17-430a-a7e8-1b12e8acc29a', 'zz', 'Plats Zama', 'Quelle sauce accompagne le Tawouk ?', '["Harissa maison", "Toum, à l''ail", "Tahiné au citron", "Chermoula fraîche"]', 1, 'Poulet mariné en brochette, sauce toum, tuiles de pita et riz au curry.', true, 1, 'qcm', null, 'carte'),
('236c9f68-ee1c-4c02-aeac-289d83ad0650', 'zz', 'À partager', 'Avec quoi est servie la Burrata Beldi ?', '["Jambon cru et roquette", "Salade César et croûtons", "Pain grillé et beurre salé", "Tartare de tomates et olives"]', 3, '170 DH le soir, 150 DH en terrasse.', true, 1, 'qcm', null, 'carte'),
