('6825919e-aefa-44b1-b801-756399f21e5e', 'zz', 'Terrasse', 'En terrasse, quel milk-shake est 100 % marocain ?', '["Vanille de Madagascar", "Fraise et basilic", "Chocolat et caramel", "Corne de Gazelle"]', 3, 'Le milk-shake Corne de Gazelle, 65 DH : parfait à raconter aux touristes.', true, 1, 'qcm', null, 'carte'),
('6fe95bbd-cc78-4823-936d-3e220cfb7fae', 'baro', 'Expérience Baro', 'À quelle heure a lieu la Mixology Class ?', '["À minuit, chaque samedi soir", "Sur demande, à 22 h au bar", "Le dimanche à midi", "Tous les jours, 17 h à 18 h"]', 3, 'Minimum 2 personnes, selon disponibilité : de la théorie à la pratique avec nos mixologues.', true, 1, 'qcm', null, 'carte'),
('95450dad-e0e7-4324-9e18-c1c29ff9332a', 'zz', 'À partager', 'Les Briouates Thalata sont farcies de…', '["Légumes du marché", "Crevettes et ail", "Trois fromages", "Viande hachée épicée"]', 2, '« Thalata » veut dire trois en arabe : trois fromages.', true, 1, 'qcm', null, 'carte'),
('b27d9ce0-704b-4d72-9226-82089152a26b', 'zz', 'À partager', 'Le Houmouss Fatteh est une fusion…', '["Marocaine et française", "Turque et grecque", "Indienne et pakistanaise", "Libanaise et syrienne"]', 3, '100 DH, idéal à partager en début de repas.', true, 1, 'qcm', null, 'carte'),
('e5378204-6089-4f29-81b7-e6d98c1a6d35', 'zz', 'Plus ou moins', 'Lequel est le plus cher ?', '["Le NoorShems", "Le Snake Dance"]', 0, 'NoorShems 170 DH, Snake Dance 160 DH.', true, 1, 'price', null, 'carte'),
