('5be2fe98-8818-4d41-b38a-841b52c4e84f', 'zz', 'À partager', 'Comment sont cuisinées les Gambas de Carthage ?', '["Grillées nature au charbon", "Crues, façon ceviche", "Poêlées à la harissa", "Frites en tempura"]', 2, '160 DH, un plat relevé : proposer un cocktail frais à côté.', true, 2, 'qcm', null, 'carte'),
('6988505b-61aa-4c21-bd37-7350964934b7', 'zz', 'Plats Zama', 'Le Tigre qui Danse est un plat de…', '["Poulet grillé", "Agneau confit", "Poisson du jour", "Filet de bœuf"]', 3, 'Servi avec gratin dauphinois à la noix de muscade. 290 DH.', true, 2, 'qcm', null, 'carte'),
('7e49fef5-f3b7-4b43-abda-079f8d64cfb3', 'zz', 'Plats Zama', 'L''Agneau Samarkand, ce sont des côtelettes avec…', '["Des frites maison au thym", "Une purée truffée maison", "Du riz basmati au curry", "Des gnocchis aux herbes"]', 3, 'Côtelettes d''agneau, beurre noisette de câpres, gnocchis aux herbes aromatiques.', true, 2, 'qcm', null, 'carte'),
('9db47196-8d02-4cfc-9049-5ea57d2f0da4', 'zz', 'Plats Zama', 'Le Loup Bar Doré est servi…', '["Frit, en beignets", "En tagine, à la chermoula", "En ceviche, au citron", "En papillote, au fenouil"]', 1, 'Avec des médaillons de pommes de terre fondants.', true, 2, 'qcm', null, 'carte'),
