('a0fdbef4-69e1-46c9-a363-d9de26d3e4f3', null, 'Bar en images', 'Le Bee''s Knees, c''est gin, citron et…', '["Du miel", "Du sucre de canne", "Du sirop d''orgeat", "De la grenadine"]', 0, 'Un classique de la Prohibition : gin, citron, miel.', true, 2, 'image', '{"img": "b8c6432d1e53"}', 'cocktails'),
('a27aee0c-5511-48cc-8c44-cdd00e6348a6', null, 'Spiritueux', 'Le mezcal San Cosme de la carte vient de quel État mexicain réputé pour le mezcal ?', '["Jalisco", "Yucatán", "Sonora", "Oaxaca"]', 3, 'Oaxaca est la capitale du mezcal, souvent au goût fumé.', true, 2, 'qcm', null, 'cocktails'),
('acda5301-aebf-4c16-b8db-90006509049a', null, 'Bar en images', 'Ce duo verre et timbale en métal, c''est…', '["Un doseur", "Un shaker Boston", "Un verre à mélange", "Un shaker cobbler"]', 1, 'Le Boston = un verre + une timbale. Le cobbler a 3 pièces avec une passoire intégrée.', true, 2, 'image', '{"img": "4bf26dc95ce1"}', 'cocktails'),
('ae7993d2-48c6-4d55-8f2e-700da1d41d31', null, 'Associations', 'Relie chaque spiritueux à son pays', '[]', 0, 'Le tour du monde au comptoir.', true, 2, 'match', '{"pairs": [["Tequila", "Mexique"], ["Cognac", "France"], ["Scotch", "Écosse"], ["Zacapa", "Guatemala"]]}', 'cocktails'),
('b701190d-731e-4b5e-a1ee-b26aa8d68e8b', null, 'Vrai ou faux', 'On sait exactement qui a inventé la Margarita.', '["Vrai", "Faux"]', 1, 'Faux ! Plusieurs bars et bartenders revendiquent sa création. Le mystère fait partie de la légende.', true, 2, 'tf', null, 'cocktails'),
('b91dfe6d-90d2-4d76-b120-9cced35bacb8', 'zz', 'Cocktails Zama', 'Le Rose de Damas, c''est…', '["Vodka, dattes et prosecco", "Gin à la rose, hibiscus, citron", "Rhum, géranium et citron vert", "Tequila infusée à la cardamome"]', 1, 'Léger et floral : gin à la rose, hibiscus maison et citron.', true, 2, 'qcm', null, 'cocktails'),
('b94d2664-0bdd-42f0-ad5a-3f84106803b4', 'zz', 'Cocktails Zama', 'Quel ingrédient marocain est mis en macération dans le Scorpion ?', '["Fleur d''oranger", "Safran", "Harissa", "Amlou"]', 2, 'Scorpion : tequila, cordial de citron aux poivrons, macération à la harissa. « Intense et épicé ».', true, 2, 'qcm', null, 'cocktails'),
('bc795c92-1179-469b-8a0c-984cf98dd7aa', 'baro', 'Cocktails Baro', 'Pourquoi le cocktail Churchill porte ce nom ?', '["Pour son goût de cigare", "Il a été créé à Londres", "C''est sa recette personnelle", "Il venait souvent à Marrakech"]', 3, 'Whisky infusé aux pruneaux, caroube, orange, safran, cannelle et bitter. « Deep & Woody », 175 DH.', true, 2, 'qcm', null, 'cocktails'),
('bf163f2a-07eb-4ba0-a4dd-a34615c77b81', null, 'Vrai ou faux', 'Un Scotch whisky doit vieillir au moins 3 ans en fût de chêne.', '["Vrai", "Faux"]', 0, 'Vrai ! C''est la règle minimum en Écosse.', true, 2, 'tf', null, 'cocktails'),
('c65ba04d-90ad-40d3-8e4d-77d96c9db8d2', 'zz', 'Cocktails Zama', 'Quel cocktail utilise un whisky infusé à l''orange avec ras el hanout et safran ?', '["Berberliner", "Marrakesh Market", "Old Fashioned", "Whisky Sour"]', 1, 'Marrakesh Market : « fumé et épicé », whisky infusé à l''orange, ras el hanout, safran, citron et bitter maison.', true, 2, 'qcm', null, 'cocktails'),
('c94fdc1b-0d88-4a34-bc29-a565fe95e713', 'baro', 'Cocktails Baro', 'Comment se servent nos shots de tequila signature ?', '["Flambés au comptoir", "Avec citron et sel uniquement", "Avec sel, olives et pickles", "Avec du Red Bull glacé"]', 2, '« À déguster comme il se doit » : un vrai rituel à présenter au client.', true, 2, 'qcm', null, 'cocktails'),
('d5656541-5967-4c16-983c-aed9f0709b86', null, 'Mixologie', 'À quoi servent les bitters (Angostura…) ?', '["À colorer le cocktail", "À assaisonner le cocktail", "À remplacer une partie de l''alcool", "À sucrer sans sirop"]', 1, 'Quelques traits suffisent : ce sont les épices du bartender.', true, 2, 'qcm', null, 'cocktails'),
('df8955bb-f59d-49d7-ace2-377c9da9e405', null, 'Vrai ou faux', 'L''Espresso Martini a été créé à Londres dans les années 1980.', '["Vrai", "Faux"]', 0, 'Vrai ! Par le bartender Dick Bradsell, pour une cliente qui voulait un verre pour la réveiller.', true, 2, 'tf', null, 'cocktails'),
('e40a4319-02e5-456b-b881-a058515b562f', null, 'Bar en images', 'Cet outil sert à…', '["Prélever de fins zestes d''agrume", "Ouvrir les huîtres", "Couper la viande", "Hacher les herbes"]', 0, 'Le zesteur prend la peau parfumée sans la partie blanche amère.', true, 2, 'image', '{"img": "47555a620378"}', 'cocktails'),
('e6f0e69f-ab24-4b31-a03b-ddbf75635f0c', 'zz', 'Cocktails Zama', 'Le Dolce Hayat contient un sorbet de…', '["Grenade", "Figue", "Mangue", "Dattes"]', 3, 'Vodka sur sorbet de dattes Majhoul, fleur de sureau et prosecco.', true, 2, 'qcm', null, 'cocktails'),
('ea4c439b-dbbf-4b14-ba47-222c440ae3ad', 'baro', 'Cocktails Baro', 'Le Mooja se savoure « dans le creux de la vague ». Ses saveurs ?', '["Gin, rose et hibiscus", "Whisky, truffe et miel", "Rhum, ananas et coco", "Tequila, poivrons, harissa"]', 2, '« Fruity & Floral », 160 DH, existe aussi sans alcool.', true, 2, 'qcm', null, 'cocktails'),
('eb87f2af-4b9c-402a-bce8-f2a5cc58fb46', null, 'Vrai ou faux', 'Un bourbon doit obligatoirement être fabriqué au Kentucky.', '["Vrai", "Faux"]', 1, 'Faux ! Il doit être fait aux États-Unis. Le Kentucky en produit la grande majorité, mais pas l''exclusivité.', true, 2, 'tf', null, 'cocktails'),
('ebf514cd-fb0f-4cbd-919a-15cb1272149e', 'baro', 'Cocktails Baro', 'Le Botanic Gin Tonic est allongé avec…', '["Eau gazeuse", "Prosecco", "Tonic suisse", "Schweppes"]', 2, 'Gin au citron vert et curcuma, gingembre, cardamome, coriandre, romarin et poivre noir.', true, 2, 'qcm', null, 'cocktails'),
('f94ef683-d7cc-447f-b937-6849db98aeca', null, 'Vrai ou faux', 'Les bartenders recommandent de secouer un Dry Martini, comme James Bond.', '["Vrai", "Faux"]', 1, 'Faux ! Un cocktail sans jus se remue : il reste limpide et soyeux. Bond, lui, le voulait secoué.', true, 2, 'tf', null, 'cocktails'),
('f9cb21db-819a-4d0a-bebb-e904e33ad4a5', null, 'Vrai ou faux', 'Le ver dans la bouteille fait partie de la tradition de tous les mezcals.', '["Vrai", "Faux"]', 1, 'Faux ! C''était surtout un coup marketing. Les grands mezcals n''en ont pas.', true, 2, 'tf', null, 'cocktails'),
('fe486e27-bb31-455f-8f22-cdc0075f65ba', null, 'Spiritueux', 'Pourquoi le mezcal a-t-il souvent un goût fumé ?', '["On y ajoute de la fumée liquide", "L''agave est cuit dans la terre", "Il vieillit dans des fûts brûlés", "À cause du ver dans la bouteille"]', 1, 'Les cœurs d''agave (piñas) sont cuits lentement dans des fosses chauffées au bois.', true, 2, 'qcm', null, 'cocktails'),
('1477a652-2761-45e5-9a5f-2df9449c0c6f', 'zz', 'Cocktails Zama', 'Le Berberliner utilise un whisky « fat-washed » à…', '["Le beurre", "L''huile d''argan", "L''huile de sésame", "L''huile d''olive"]', 1, 'Fat-wash à l''huile d''argan, amlou, miel d''amande et bitter. « Bold & strong ».', true, 3, 'qcm', null, 'cocktails'),
('14f176c0-6e63-4cd3-aefb-95d52ea284b2', 'zz', 'Cocktails Zama', 'La tequila du Cardarita est infusée à…', '["La cannelle", "La vanille", "La cardamome", "Le safran"]', 2, 'Tequila à la cardamome et cordial de céleri au citron. 170 DH.', true, 3, 'qcm', null, 'cocktails'),
('16827270-9211-4b36-8d52-5e2fafd1a08c', null, 'Vrai ou faux', 'Le Penicillin est un cocktail créé au XIXe siècle par un médecin.', '["Vrai", "Faux"]', 1, 'Faux ! Il a été créé en 2005 à New York par le bartender Sam Ross, au bar Milk & Honey.', true, 3, 'tf', null, 'cocktails'),
('22f22e0a-00bf-4dad-aac8-2630be49a653', null, 'Vrai ou faux', 'Le Cognac est une eau-de-vie de raisin.', '["Vrai", "Faux"]', 0, 'Vrai ! Distillé deux fois puis vieilli en fût de chêne, dans la région de Cognac.', true, 3, 'tf', null, 'cocktails'),
('41b973e3-438d-4c50-90f7-b63d0adf3bfd', 'baro', 'Cocktails Baro', 'Quelle différence entre le Marrakesh Market du Baromètre et celui de ZamaZama ?', '["Aucune", "Celui de Zama est sans alcool", "La version Zama ajoute du safran", "Celui du Baro est à la tequila"]', 2, 'Base commune : whisky infusé à l''orange, ras el hanout, citron et bitter maison.', true, 3, 'qcm', null, 'cocktails'),
('490e71e8-293d-41c6-a4b5-58e6951b6f09', 'baro', 'Cocktails Baro', 'Le Lust Martini est décrit comme…', '["Amer et sec, au vermouth italien", "Fumé et boisé, au whisky", "Salé et umami, à l''olive", "Fruité, à la mangue et passion"]', 3, '« Élégant, mais joueur ». Fait partie des choix de l''Eye Contact.', true, 3, 'qcm', null, 'cocktails'),
('99036074-d519-44b0-b849-f739440dfe38', 'baro', 'Cocktails Baro', 'Quel cocktail Baromètre est un Mojito revisité avec rhum à la citronnelle, cordial clarifié et espuma ?', '["Le Mojito Soltane", "Le Mojito Especial", "Le Mooja", "L''Antidote"]', 1, '130 DH. À ne pas confondre avec le Mojito Soltane de ZamaZama.', true, 3, 'qcm', null, 'cocktails'),
('9b923184-760d-4f89-a2aa-0534ab9df759', 'zz', 'Cocktails Zama', 'Lequel de ces signatures n''existe PAS en virgin ?', '["Rose de Damas", "Scorpion", "Berberliner", "Snake Dance"]', 2, 'NoorShems, Dolce Hayat et Berberliner n''ont pas de version virgin.', true, 3, 'qcm', null, 'cocktails'),
('b5df6633-b2ff-4503-bd98-e304fe3bd87a', null, 'Vrai ou faux', 'À l''origine, la couleur rouge du Campari venait d''un insecte, la cochenille.', '["Vrai", "Faux"]', 0, 'Vrai ! Le colorant carmin a été remplacé depuis par un colorant artificiel.', true, 3, 'tf', null, 'cocktails'),
('c3adf957-8af8-4d6c-86ba-dafe816af476', null, 'Vrai ou faux', 'La Piña Colada est la boisson nationale de Porto Rico.', '["Vrai", "Faux"]', 0, 'Vrai ! Officiellement depuis 1978.', true, 3, 'tf', null, 'cocktails'),
('cb8b323f-0577-4a08-8bc8-94d971a83115', 'zz', 'Cocktails Zama', 'Le Tomatini est surmonté d''une mousse légère de…', '["Blanc d''œuf", "Yaourt", "Fromage frais", "Coco"]', 2, 'Gin, eau de tomate à l''origan clarifiée et carbonatée, mousse de fromage frais.', true, 3, 'qcm', null, 'cocktails'),
('d9a29db8-b143-4b4a-8bea-903892a3a999', 'baro', 'Cocktails Baro', 'Quelle est la différence entre nos shots Snake Bite et Antidote ?', '["Antidote est au whisky fumé", "Ce sont les mêmes recettes", "Snake Bite tequila, Antidote gin", "Snake Bite est sans alcool, Antidote non"]', 2, '80 DH chacun : le poison et son remède, à proposer en duo.', true, 3, 'qcm', null, 'cocktails'),
('e09b96a3-969e-4744-aab6-75f7ada2aa68', 'baro', 'Cocktails Baro', 'Le Crystal Meth associe tequila, citron et gingembre avec…', '["Truffe noire et miel", "Rose et camomille", "Curaçao et cardamome", "Pruneau et caroube"]', 2, '« Bright & Bold » : une alchimie intense, au visuel bleu.', true, 3, 'qcm', null, 'cocktails'),
('e55db082-2b87-4164-9c66-6c12d6954ed8', null, '50 Best', 'Ce qui fait un bar de niveau 50 Best, c''est d''abord…', '["Une très longue carte", "Un décor très cher", "Des prix très bas", "L''hospitalité"]', 3, 'Les meilleurs bars du monde sont d''abord des maisons d''accueil : on se souvient de comment on a été reçu.', true, 3, 'qcm', null, 'cocktails'),
('f9ce157c-f01b-4db9-9d10-e75741db4c25', null, 'Mixologie', 'La « dilution » dans un cocktail, c''est…', '["Un sirop de sucre", "Un type de verre", "L''eau de la glace", "Une erreur de dosage"]', 2, 'La glace qui fond fait partie de la recette : sans dilution, le cocktail est trop fort et déséquilibré.', true, 3, 'qcm', null, 'cocktails'),
('fe0984c7-0212-441c-a669-67cfa695681d', null, 'Spiritueux', 'Le Zacapa 23 de la carte est un rhum de quel pays ?', '["Guatemala", "Jamaïque", "Martinique", "Cuba"]', 0, 'Un rhum vieilli en altitude, réputé pour sa rondeur.', true, 3, 'qcm', null, 'cocktails'),
('028333ad-e4be-4ef0-a67c-638150f756df', null, 'Cuisine en images', 'À quoi sert la balance en cuisine ?', '["Décorer", "Respecter les grammages des fiches techniques", "Peser les clients", "À rien"]', 1, 'Même grammage = même goût, même coût, même assiette.', true, 1, 'image', '{"img": "a5a6d5511bdd"}', 'cuisine'),
('105783c8-7966-432e-8bc2-1bc5f8962b2f', null, 'Cuisine en images', 'Comment s''appelle cet ustensile ?', '["Une pince", "Une écumoire", "Un fouet", "Un chinois"]', 2, 'Le fouet incorpore de l''air : crème montée, blancs, sauces.', true, 1, 'image', '{"img": "5e64093191b2"}', 'cuisine'),
('215c6ceb-6b95-48ce-a195-c9f94006c5e4', null, 'Cuisine en images', 'Température d''un frigo de produits frais ?', '["0 à 4 °C", "−18 °C", "12 °C", "8 à 10 °C"]', 0, '0 à 4 °C pour les produits frais. −18 °C, c''est le congélateur.', true, 1, 'image', '{"img": "ce1c63ed8cf5"}', 'cuisine'),
('21ba0385-d3fd-4f20-aaf3-0f814e5427b8', null, 'Cuisine', 'Comment décongèle-t-on un produit ?', '["Sur le plan de travail", "Dans l''eau chaude", "Au soleil", "Au réfrigérateur"]', 3, 'Lentement au froid : jamais à température ambiante.', true, 1, 'qcm', null, 'cuisine'),
('6638d7a5-8757-4caf-9066-18ff20218984', null, 'Cuisine en images', 'Comment s''appelle cet ustensile ?', '["Une louche", "Une écumoire", "Une cuillère à soupe", "Un chinois"]', 0, 'La louche sert à servir et doser les liquides : soupes, sauces.', true, 1, 'image', '{"img": "d61da9544421"}', 'cuisine'),
('70edc250-208e-40fe-848b-d97d2de2af08', null, 'Cuisine', 'La planche à découper rouge est réservée…', '["Au poisson cru", "Au pain et aux laitages", "Aux légumes", "À la viande crue"]', 3, 'Code couleur courant : rouge viande crue, bleu poisson, vert légumes, jaune volaille, blanc pain et laitages.', true, 1, 'qcm', null, 'cuisine'),
('78fb80dc-ce33-497d-bf75-4bed165e5c70', null, 'Cuisine', 'À quelle température garde-t-on les produits frais au réfrigérateur ?', '["Entre 0 et 4 °C", "Entre 8 et 12 °C", "À −18 °C", "Autour de 15 °C"]', 0, '0 à 4 °C pour les produits très périssables. Au-dessus, les bactéries se multiplient vite.', true, 1, 'qcm', null, 'cuisine'),
('8c0443ed-d60f-4616-bc49-c4a6605ead04', null, 'Cuisine', 'Un plat chaud en attente de service doit rester à…', '["Température ambiante", "25 °C", "40 °C", "63 °C minimum"]', 3, 'En dessous de 63 °C, on entre dans la zone où les bactéries se développent.', true, 1, 'qcm', null, 'cuisine'),
('bee855ab-8e6f-4d14-af6e-7dc498e3916e', null, 'Cuisine en images', 'Une préparation maison sans étiquette au frigo…', '["Est donnée au personnel", "Va au congélateur", "Doit être jetée", "Peut servir si elle sent bon"]', 2, 'Pas d''étiquette = pas de date = on jette.', true, 1, 'image', '{"img": "d8784714dbb0"}', 'cuisine'),
('c079967d-3251-4d4c-8f8a-c7bc374f028b', null, 'Cuisine', 'On peut recongeler un produit qui a été décongelé.', '["Vrai", "Faux"]', 1, 'Faux ! Un produit décongelé ne se recongèle jamais tel quel. On le cuisine, ou on le jette.', true, 1, 'tf', null, 'cuisine'),
('d09df3b0-af48-46d5-90fa-49e90b5741ba', null, 'Associations', 'Relie chaque planche à son usage', '[]', 0, 'Le code couleur évite les contaminations.', true, 1, 'match', '{"pairs": [["Rouge", "Viande crue"], ["Bleue", "Poisson"], ["Verte", "Légumes"], ["Jaune", "Volaille"]]}', 'cuisine'),
('ddcffb8b-8a56-4a64-a12b-5d5828b3e4d0', null, 'Cuisine en images', 'Comment s''appelle cet ustensile ?', '["Une écumoire", "Un fouet", "Une louche", "Une spatule"]', 3, 'La spatule coudée sert à retourner, lisser et dresser.', true, 1, 'image', '{"img": "8340633360a1"}', 'cuisine'),
('ed81136e-45cc-461c-a30f-4baf83f4b738', null, 'Cuisine', 'La température d''un congélateur doit être de…', '["0 °C tout juste", "−5 °C environ", "−18 °C ou moins", "−2 °C ou moins"]', 2, '−18 °C bloque le développement des bactéries.', true, 1, 'qcm', null, 'cuisine'),
('f48d406a-fb0d-4322-9c04-5e9ce1c37825', null, 'Cuisine en images', 'Tu te coupes en cuisine. Premier réflexe ?', '["Continuer et soigner plus tard", "Mettre le doigt dans la glace", "Arrêter, laver, désinfecter, pansement et gant", "Rien, c''est petit"]', 2, 'Un pansement bleu et un gant : pour toi et pour l''assiette.', true, 1, 'image', '{"img": "ce81ff78adb6"}', 'cuisine'),
('08d102ad-8a53-4294-90d6-7c205caa6ab1', null, 'Cuisine', 'Combien d''allergènes majeurs doivent être signalés selon la réglementation européenne ?', '["5", "14", "30", "8"]', 1, 'Gluten, crustacés, œufs, poissons, arachides, soja, lait, fruits à coque, céleri, moutarde, sésame, sulfites, lupin, mollusques.', true, 2, 'qcm', null, 'cuisine'),
('32a4d5ca-c415-471b-8577-9ea568116478', null, 'Cuisine', 'Une friteuse prend feu. Le bon réflexe ?', '["Jeter un seau d''eau dessus", "Déplacer vite la friteuse", "Couper le feu et étouffer", "Souffler fort sur les flammes"]', 2, 'Jamais d''eau sur de l''huile en feu : elle provoque une explosion de flammes.', true, 2, 'qcm', null, 'cuisine'),
('64f917ca-6550-4733-9273-8a8556f7ef20', null, 'Cuisine', 'La « contamination croisée », c''est…', '["Une erreur de commande", "Un transfert de microbes", "Un mélange de deux sauces", "Un plat beaucoup trop cuit"]', 1, 'Exemple : couper du poulet cru puis une salade avec le même couteau.', true, 2, 'qcm', null, 'cuisine'),
('7e29b11e-da65-4224-bf13-ba1c82e310fd', null, 'Cuisine', 'Dans une brigade, qui seconde directement le chef ?', '["Le plongeur", "Le sous-chef", "Le chef de rang", "Le commis"]', 1, 'Le sous-chef (ou second) remplace le chef en son absence.', true, 2, 'qcm', null, 'cuisine'),
('9d754405-6f19-455b-ab48-48560467b4de', null, 'Cuisine en images', 'Ce crustacé à grosses pinces, c''est…', '["Une langouste", "Un homard", "Une écrevisse", "Un crabe"]', 1, 'Le homard a deux grosses pinces. La langouste n''en a pas.', true, 2, 'image', '{"img": "c55bda3a01cd"}', 'cuisine'),
('b1debc4c-f848-4420-b20e-5359c4b693ce', null, 'Cuisine', 'Les montres et bracelets sont interdits en cuisine.', '["Vrai", "Faux"]', 0, 'Vrai ! Ils retiennent les bactéries et peuvent tomber dans les plats.', true, 2, 'tf', null, 'cuisine'),
('b2662b1b-1960-49e2-98f6-03dbb1346c0d', null, 'Cuisine', 'Un client allergique aux fruits à coque commande. Que fais-tu en cuisine ?', '["Vérifier et prévenir le chef", "En mettre un peu moins", "Enlever les noix visibles", "Rien, c''est au serveur de gérer"]', 0, 'Une trace suffit à déclencher une réaction grave.', true, 2, 'qcm', null, 'cuisine'),
('da454f09-e798-4aff-b10e-5897e9bda9e3', null, 'Cuisine en images', 'Cette passoire conique s''appelle…', '["Un entonnoir", "Un chinois", "Un tamis plat", "Une passoire à thé"]', 1, 'Le chinois filtre les sauces et les fonds pour une texture lisse.', true, 2, 'image', '{"img": "583a4f58e508"}', 'cuisine'),
('dea9714c-a7cd-4599-88f3-52a507095dbd', null, 'Cuisine', 'Une préparation maison mise au frigo doit porter…', '["Nom, date et date limite", "Le prénom du cuisinier", "Seulement le prix", "Rien, c''est pour aujourd''hui"]', 0, 'Sans étiquette, un produit maison doit être jeté.', true, 2, 'qcm', null, 'cuisine'),
('fa6d2569-442d-4a9f-b7ab-3335b6a5e754', null, 'Cuisine en images', 'Une éponge sale en cuisine, c''est…', '["Pratique pour les planches à viande", "Un nid à bactéries : on la change souvent", "Mieux qu''un torchon propre", "Sans danger si elle est rincée"]', 1, 'L''éponge humide est l''un des objets les plus contaminés d''une cuisine.', true, 2, 'image', '{"img": "ff1b0ad4092f"}', 'cuisine'),
