('39619078-e7b5-5386-a2d6-ee8f723329b0', null, 'Escapades · Atlas', 'De quel village part-on habituellement pour gravir le Toubkal ?', '["Agadir", "Ouarzazate", "Imlil", "Essaouira"]', 2, 'Imlil, à environ 1 740 m d''altitude : le camp de base des randonneurs.', true, 1, 'qcm', null, 'escapades'),
('41c46ef3-2b99-510b-8964-f190d21459ed', null, 'Escapades · Côte', 'Quel était l''ancien nom d''Essaouira ?', '["Tingis", "Volubilis", "Mogador", "Lixus"]', 2, 'Mogador. Le nom viendrait du phénicien « migdol », la petite forteresse.', true, 1, 'qcm', null, 'escapades'),
('8dfe77e4-173f-5414-8d20-88f39b71b1a9', null, 'Escapades · Désert et kasbahs', 'Quel film a été tourné en partie à Aït Ben Haddou ?', '["Titanic", "Avatar", "Le Roi Lion", "Gladiator"]', 3, 'Gladiator, mais aussi Lawrence d''Arabie, La Momie et la série Game of Thrones.', true, 1, 'qcm', null, 'escapades'),
('9185f8ff-d514-5d16-8b7d-1488e616c0b2', null, 'Raconte une escapade', '« On a une journée, on voudrait voir la montagne sans trop rouler. »', '["« Merzouga, c''est à une heure. »", "« La vallée de l''Ourika, à une heure. »", "« Le Toubkal, aller-retour en un matin. »", "« Les cascades d''Ouzoud, à 30 minutes. »"]', 1, 'Une idée précise, avec la durée du trajet : le client sait tout de suite si ça lui convient.', true, 1, 'scene', null, 'escapades'),
('9934c3ae-b085-59eb-8340-904587a0e720', null, 'Escapades · Atlas', 'Quelle est la hauteur des cascades d''Ouzoud ?', '["Environ 110 mètres", "Environ 1 000 mètres", "Environ 10 mètres", "Environ 500 mètres"]', 0, 'Environ 110 m : les plus hautes du Maroc, à environ 150 km de Marrakech.', true, 1, 'qcm', null, 'escapades'),
('a30073e7-4f07-594f-a248-dc05b796ea90', null, 'Escapades · Côte', 'Pourquoi Essaouira attire-t-elle autant de surfeurs et de kitesurfeurs ?', '["Pour ses vagues de 20 m", "Pour ses eaux à 35 °C", "Pour ses plages privées", "Pour son vent régulier"]', 3, 'Les alizés soufflent presque toute l''année : un paradis pour la glisse… et une ville toujours fraîche l''été.', true, 1, 'qcm', null, 'escapades'),
('aeec75f7-f964-553f-978f-b0d10d8c9ee8', null, 'Escapades · Désert et kasbahs', 'Quelle est la particularité du désert d''Agafay ?', '["Il est au bord de la mer", "Il est couvert de neige", "C''est le plus grand désert de sable du monde", "C''est un désert de pierres, sans grandes dunes"]', 3, 'Agafay est une hamada, un plateau de pierres et de collines, à environ 35 km de Marrakech.', true, 1, 'qcm', null, 'escapades'),
('b615a4b6-0c53-5df8-8a4a-6889637bd337', null, 'Escapades · Atlas', 'À quelle distance de Marrakech se trouve la vallée de l''Ourika ?', '["Environ 300 km", "Environ 600 km", "Environ 5 km", "Environ 60 km"]', 3, 'Une soixantaine de kilomètres : l''escapade nature la plus simple depuis Marrakech.', true, 1, 'qcm', null, 'escapades'),
('fe959647-d8fd-5876-8933-77ee4071a8e9', null, 'Escapades · Désert et kasbahs', 'Qu''est-ce qu''un ksar, comme Aït Ben Haddou ?', '["Un village fortifié", "Un palais de marbre", "Un marché couvert", "Un jardin royal"]', 0, 'Un village fortifié aux maisons de terre serrées les unes contre les autres, sur l''ancienne route des caravanes.', true, 1, 'qcm', null, 'escapades'),
('01f644d6-8a07-58a1-a2b9-d5d6f610f140', null, 'Escapades · Désert et kasbahs', 'Depuis quand Aït Ben Haddou est-il au patrimoine mondial de l''UNESCO ?', '["1987", "2015", "1950", "2001"]', 0, 'Depuis 1987. Le ksar surplombe l''oued Ounila.', true, 2, 'qcm', null, 'escapades'),
('034b4297-9cd2-5eb1-8815-5cf956295995', null, 'Escapades · Atlas', 'Quelle randonnée célèbre part du village de Setti Fatma, dans l''Ourika ?', '["Les sept cascades", "La vallée des roses", "Les gorges du Todra", "Le tour du Toubkal"]', 0, 'La randonnée des sept cascades, avec des cafés installés au bord de l''eau.', true, 2, 'qcm', null, 'escapades'),
