('2416401a-f92e-5cff-a3f6-4873c481f8b7', null, 'Escapades · Atlas', 'Qu''est-ce que le lac Lalla Takerkoust ?', '["Un lac salé, près d''Essaouira", "Un lac naturel, en plein Sahara", "Un lac de barrage, près de l''Atlas", "Une piscine royale ancienne"]', 2, 'Un lac de retenue au pied de l''Atlas : baignade, kayak et déjeuner face aux montagnes.', true, 2, 'qcm', null, 'escapades'),
('6daf860b-01b1-599b-bd5e-3689b58be803', null, 'Escapades · Désert et kasbahs', 'Pour voir de grandes dunes de sable, il suffit d''aller à Agafay.', '["Vrai", "Faux"]', 1, 'Faux : les grandes dunes, c''est Merzouga ou Zagora, à plusieurs heures de route. Agafay, c''est le désert de pierres tout proche.', true, 2, 'tf', null, 'escapades'),
('7c4472c4-9e31-5be3-9e9a-3d0d46d982f3', null, 'Escapades · Côte', 'Quel grand festival de musique a lieu chaque année à Essaouira depuis 1998 ?', '["Le festival Gnaoua", "Le festival de jazz de Montreux", "Le festival de Cannes", "Le festival des musiques sacrées"]', 0, 'Le festival Gnaoua, en général fin juin : des maâlems gnaoua jouent avec des artistes du monde entier.', true, 2, 'qcm', null, 'escapades'),
('7e257adb-ffab-5be9-bea3-2e3a1abfd6c0', null, 'Escapades · Côte', 'Depuis quand la médina d''Essaouira est-elle au patrimoine mondial de l''UNESCO ?', '["2001", "1985", "2020", "1960"]', 0, 'Depuis 2001 : un rare exemple de ville fortifiée du XVIIIe siècle mêlant styles européen et marocain.', true, 2, 'qcm', null, 'escapades'),
