('a09365bd-6c46-53eb-9230-dc1572b2b68f', null, 'Raconte une escapade', '« On rêve du désert, mais on n''a qu''une soirée. »', '["« Agafay, à 45 min : des pierres, pas des dunes. »", "« Merzouga, on y va et on rentre ce soir. »", "« Agafay, il y a les plus hautes dunes du pays. »", "« Zagora, c''est à une demi-heure d''ici. »"]', 0, 'Proposer la bonne option et préciser honnêtement ce qu''on y verra évite toute déception.', true, 2, 'scene', null, 'escapades'),
('b9cb273f-2a3a-5fd8-b043-f9542f9cbb69', null, 'Raconte une escapade', '« Un ami nous a parlé d''Essaouira, ça vaut le coup ? »', '["« Oui, à 2 h 30 : médina, port et poisson. »", "« Oui, à 30 minutes, juste à côté. »", "« Oui, pour ses grandes dunes de sable. »", "« Oui, mais c''est fermé l''hiver. »"]', 0, 'Donner le temps de trajet et trois raisons d''y aller : c''est un conseil qu''on retient.', true, 2, 'scene', null, 'escapades'),
('bc27105c-49a2-53bb-a44a-1e45d6ec53c6', null, 'Escapades · Atlas', 'On peut skier le matin dans l''Atlas et se baigner l''après-midi à Marrakech.', '["Vrai", "Faux"]', 0, 'Vrai, certains jours de printemps : Oukaïmeden n''est qu''à environ 1 h 30 de route de la ville.', true, 2, 'tf', null, 'escapades'),
('bf011993-4442-5557-8a81-a2013c610669', null, 'Escapades · Désert et kasbahs', 'Pourquoi surnomme-t-on Ouarzazate le « Hollywood de l''Afrique » ?', '["Pour ses palmiers", "Pour son grand festival de musique", "Pour ses grands studios de cinéma", "Pour ses stars qui y habitent"]', 2, 'Ses studios, comme Atlas Studios fondé en 1983, accueillent des tournages du monde entier.', true, 2, 'qcm', null, 'escapades'),
('c08ba706-14bc-50f7-b864-d05ff2c1d616', null, 'Escapades · Désert et kasbahs', 'Quelle route relie Marrakech à Ouarzazate à travers le Haut Atlas ?', '["Le col du Mont-Blanc", "La route de la soie", "Le col du Saint-Gothard", "Le col du Tizi n''Tichka"]', 3, 'Le Tizi n''Tichka, à plus de 2 200 m : une route de lacets ouverte en 1936.', true, 2, 'qcm', null, 'escapades'),
