('cbd60852-7457-4700-aad6-f647cb5eb1ad', null, 'Accords mets et vins', 'Un client prend le Tfaya Chèvre Chaud. Quel vin proposer ?', '["Le Rioja Reserva", "Un rouge très boisé", "Le Touraine Sauvignon", "Le Pommard 1er Cru"]', 2, 'Chèvre et Sauvignon de Loire : l''accord classique, l''acidité répond au fromage.', true, 2, 'qcm', null, 'vins'),
('d8757130-6850-44db-bdd1-bffa333614d5', null, 'Vins', 'Que signifie « Cru Bourgeois » pour le Château Le Vieux Fort ?', '["Un vin réservé à la bourgeoisie", "Un vin issu de l''agriculture bio", "Un vin d''un seul cépage", "Un classement de châteaux du Médoc"]', 3, 'Classification bordelaise reconnaissant la qualité de châteaux du Médoc.', true, 2, 'qcm', null, 'vins'),
('ded2f7ad-8aa6-4e05-a0d1-8e2712a20021', null, 'Vins', 'Le Domaine des Ouled Thaleb a fêté en 2023…', '["Ses 20 ans", "Son ouverture", "Ses 50 ans", "Ses 100 ans"]', 3, 'Créé en 1923, il a célébré son centenaire avec une « Cuvée du Siècle ». Un des plus anciens domaines du Maroc.', true, 2, 'qcm', null, 'vins'),
('e352779a-c8ba-4483-b1db-f9380599e5e5', null, 'Vins en images', 'Le champagne se sert idéalement à…', '["16 °C", "2 °C", "8 à 10 °C", "Température ambiante"]', 2, 'Trop froid, il perd ses arômes ; trop chaud, il mousse.', true, 2, 'image', '{"img": "d9f7163d1df0"}', 'vins'),
('e4939a3e-bf01-4494-a80b-ef80303eab2f', null, 'Vins en images', 'On remplit un verre à vin rouge jusqu''à…', '["Environ un tiers", "La moitié minimum", "Peu importe", "Ras bord"]', 0, 'Le vide laisse le vin respirer et le client le faire tourner.', true, 2, 'image', '{"img": "5ba8d3b98bb8"}', 'vins'),
('e620afaa-123e-43c1-857c-48306495df55', null, 'Vins en images', 'Ouvrir le champagne à table : le bon geste ?', '["Tenir le bouchon et tourner la bouteille, sans bruit", "Viser le plafond", "Secouer la bouteille avant", "Faire sauter le bouchon"]', 0, 'Le bouchon se libère en douceur, avec un léger soupir.', true, 2, 'image', '{"img": "83ca22134257"}', 'vins'),
('08ea8159-c676-4de0-a3c4-1ea2c8c609d5', null, 'Accords mets et vins', 'Le principe de l''« accord régional », c''est…', '["Servir le vin à température ambiante", "Choisir le vin le moins cher", "Un plat et un vin du même terroir", "Servir le vin de la région du client"]', 2, 'Un tajine avec un vin marocain, une burrata avec un vin italien : ça marche presque toujours.', true, 3, 'qcm', null, 'vins'),
('3b3b1da6-1209-42e0-abef-d5cc8199b289', null, 'Vins', 'Chassagne-Montrachet est surtout célèbre pour…', '["Ses rosés de Provence", "Ses grands blancs", "Ses effervescents", "Ses vins doux"]', 1, 'Côte de Beaune, Bourgogne : une des grandes adresses mondiales du Chardonnay. 2 500 DH sur notre carte.', true, 3, 'qcm', null, 'vins'),
('3c488170-a2b8-4502-bd27-dad2c4e5f214', null, 'Vins', 'Le Château Roslane porte une mention rare au Maroc. Laquelle ?', '["DOCG", "Grand Cru Classé", "AOC Premier Cru", "Cru Bourgeois"]', 2, 'Les Coteaux de l''Atlas Premier Cru est la seule appellation d''origine contrôlée du Maroc.', true, 3, 'qcm', null, 'vins'),
('403416e1-828f-45fa-b8aa-76f313a9d57e', null, 'Vins', 'Un Rioja « Reserva » rouge, c''est au minimum…', '["10 ans en bouteille", "6 mois en cuve inox", "3 ans, dont 1 en fût", "Aucune règle précise"]', 2, 'La mention garantit un vin élevé longtemps : plus rond, plus complexe.', true, 3, 'qcm', null, 'vins'),
('49c3b7e9-e8f2-4d35-9408-b54a814ba09a', null, 'Vins', 'Le Carmenère, autre cépage du CB Signature, est devenu l''emblème de quel pays ?', '["L''Afrique du Sud", "L''Argentine", "L''Espagne", "Le Chili"]', 3, 'Originaire de Bordeaux, presque disparu en France, il a trouvé une seconde vie au Chili.', true, 3, 'qcm', null, 'vins'),
('4f0653cc-490c-4c49-a0b7-a1df23929752', null, 'Vins', 'Chablis : quel est l''ordre de qualité, du plus simple au plus prestigieux ?', '["Chablis, Petit Chablis, Grand Cru, Premier Cru", "Il n''y a pas de hiérarchie", "Grand Cru, Premier Cru, Chablis, Petit Chablis", "Petit Chablis, Chablis, Premier Cru, Grand Cru"]', 3, 'Notre Petit Chablis est l''entrée de gamme fraîche et minérale de l''appellation.', true, 3, 'qcm', null, 'vins'),
('5ade3cbb-54a3-45e9-a101-7f72ed4872f9', null, 'Associations', 'Relie chaque vin à sa température de service', '[]', 0, 'La bonne température change tout.', true, 3, 'match', '{"pairs": [["Champagne", "6 à 8 °C"], ["Blanc sec", "8 à 12 °C"], ["Rouge", "15 à 18 °C"]]}', 'vins'),
('7c112252-4748-427b-a41f-80ddc6845134', null, 'Associations', 'Relie chaque vin à son cépage', '[]', 0, 'Expert en vins !', true, 3, 'match', '{"pairs": [["Pommard", "Pinot Noir"], ["Chianti", "Sangiovese"], ["Rioja", "Tempranillo"], ["Touraine", "Sauvignon Blanc"]]}', 'vins'),
('89bd0dde-3d59-4d05-9d0e-a0e2e0196d7c', null, 'Vins en images', 'Avec un fromage de chèvre frais, l''accord le plus classique ?', '["Un champagne doux", "Un Bordeaux très tannique", "Un Sancerre blanc", "Un porto vintage"]', 2, 'Sauvignon de Loire et chèvre : un mariage historique.', true, 3, 'image', '{"img": "9e9ee23046cb"}', 'vins'),
('9515a8c4-f607-40cf-abb8-b34932a1173d', null, 'Vins', 'Le Marselan (dans le CB Signature) est un croisement de…', '["Pinot Noir et Gamay", "Chardonnay et Sauvignon", "Merlot et Syrah", "Cabernet et Grenache"]', 3, 'Créé en France en 1961, il marie la structure du Cabernet et le fruit du Grenache.', true, 3, 'qcm', null, 'vins'),
('b26132b9-8600-4490-a862-6892d10f7c7c', null, 'Vins', 'Dans Studio by Miraval, le « Rolle » est aussi connu sous le nom de…', '["Ugni blanc", "Muscat", "Vermentino", "Sauvignon"]', 2, 'Rolle en Provence, Vermentino en Italie et en Corse : blanc frais et aromatique.', true, 3, 'qcm', null, 'vins'),
('b4d733af-3980-49d3-bece-709d7e87daf4', null, 'Accords mets et vins', 'Pourquoi éviter un rouge très tannique avec un plat pimenté (Gambas harissa) ?', '["Le vin devient trop sucré", "Le plat refroidit plus vite", "Le vin perd tout son fruit", "Le piquant est accentué"]', 3, 'Avec le piment, préférer un rosé, un blanc aromatique ou un rouge léger et frais.', true, 3, 'qcm', null, 'vins'),
('b688197a-1a96-4ada-b8a3-66f07c8afca5', null, 'Accords mets et vins', 'Pourquoi un vin acide va bien avec un plat gras ou fromager (burrata, brie pané) ?', '["L''acidité fait fondre le fromage", "Ce n''est pas vrai", "L''acidité nettoie le palais du gras", "Pour réchauffer le plat"]', 2, 'C''est un principe de base : l''acidité allège et relance l''appétit.', true, 3, 'qcm', null, 'vins'),
('c94283a2-4771-46ed-a099-73f859746d17', 'zz', 'Vins', 'Quel vin rouge de la carte est un Pinot Noir de Bourgogne premier cru ?', '["Médaillon rouge", "Pommard 1er Cru", "Chianti Classico", "Côte du Rhône Guigal"]', 1, 'Domaine Jean-Marc Boillot, 2 600 DH : la grande bouteille rouge de la carte.', true, 3, 'qcm', null, 'vins'),
('cf32c2bb-1af6-4dd5-84de-1b5ab509236c', null, 'Vins', 'La maison Guigal est installée à Ampuis, dans quelle appellation célèbre ?', '["Sancerre", "Champagne", "Margaux", "Côte-Rôtie"]', 3, 'Guigal est une des grandes maisons du nord de la Vallée du Rhône.', true, 3, 'qcm', null, 'vins'),
('d4a4bd6c-c411-4a3b-b926-b486f819f961', null, 'Plus ou moins', 'Quelle bouteille est la plus chère ?', '["Chassagne-Montrachet", "Pommard 1er Cru"]', 1, 'Pommard 2 600 DH, Chassagne-Montrachet 2 500 DH.', true, 3, 'price', null, 'vins'),
('fde5393e-c73e-4077-97cb-9564820209c7', 'zz', 'Vins', 'Le Petit Chablis de la carte est un vin blanc issu de quel cépage ?', '["Pinot Grigio", "Chardonnay", "Viognier", "Sauvignon blanc"]', 1, 'Comme tous les Chablis : 100 % Chardonnay.', true, 3, 'qcm', null, 'vins')
