insert into daraja.fiches (id, venue, section, title, story, cocktail, wine, why, pitch, sort, active, updated_by, updated_at) values
('0be22ef1-50b4-4956-999c-221190d41627', 'baro', 'plat', 'Le Tigre qui pleure', 'Le nom vient de Thaïlande : le cuisinier pleurait devant une viande trop bonne pour la partager.', 'Marrakesh Market', 'S de Siroua (Syrah)', 'La marinade asiatique et le bœuf appellent du poivré : le ras el hanout du cocktail et la Syrah reprennent cette chaleur sans l''écraser.', '« C''est notre bœuf le plus parfumé. Avec, je vous conseille la Syrah de Siroua, elle est née pour les épices. »', 10, true, null, '2026-11-16T17:25:45.604315+00:00'),
('8726e864-e139-4fd7-a1e7-2c7a31e73a83', 'baro', 'plat', 'Pêche Atlantique', 'Le poisson du jour arrive de l''Atlantique marocain.', 'Rosée du Matin', 'Petit Chablis', 'Le beurre blanc demande un vin tendu et minéral qui nettoie le palais ; rose et camomille restent légères comme le poisson.', '« Le poisson est arrivé ce matin. Un Petit Chablis bien frais, et vous êtes au bord de l''océan. »', 20, true, null, '2026-11-16T17:25:45.604315+00:00'),
('bfd18283-10a2-46f9-afd3-1b879702be75', 'baro', 'plat', 'Tortellonis aux cèpes', 'La tuile de parmesan du Truffle on the Rocks répond au vieux parmesan de l''émulsion.', 'Truffle on the Rocks', 'Bourgogne Pinot Noir', 'Cèpes, parmesan et truffe parlent la langue de l''umami ; le Pinot Noir a des arômes de sous-bois qui prolongent le plat.', '« Pour les tortellonis, je vous propose le Pinot Noir : il sent la forêt, comme les cèpes. »', 30, true, null, '2026-11-16T17:25:45.604315+00:00'),
('d71a91f3-3c34-4efe-8a14-e769326ce7e4', 'baro', 'plat', 'Héritage Marocain', 'Une recette de grand-mère ; l''Apothicaire, signature de la maison depuis 2016, s''inspire des remèdes de nos aïeules.', 'Apothicaire', 'Ait Souala Viognier', 'Le citron confit appelle acidité et herbes ; le Viognier, aux notes d''abricot, adoucit la sauce sans la couvrir.', '« Deux recettes de grand-mère sur la même table : le poulet au citron confit et l''Apothicaire. »', 40, true, null, '2026-11-16T17:25:45.604315+00:00'),
('d7f19a31-5752-48c4-9742-419d2a57e1d0', 'baro', 'entree', 'Pastilla aux fruits de mer', 'Le safran vient de Taliouine, où le soleil fait naître l''épice la plus chère du monde.', 'Liquid Sunshine', 'Roslane 1er Cru blanc', 'La crème au safran répond au safran infusé dans la tequila ; le Chardonnay, rond, épouse la crème.', '« Le safran de Taliouine dans l''assiette et dans le verre : on fait le voyage en entier ? »', 50, true, null, '2026-11-16T17:25:45.604315+00:00'),
('0351548f-0353-44b7-b6bc-52d404168fcf', 'baro', 'entree', 'Cigars de Lalla', 'Des cigares au poulet et gingembre, roulés à la main comme pour les fêtes.', 'Penicillin', 'Pinot Grigio', 'Le gingembre du plat et du cocktail se répondent ; le Pinot Grigio, frais et léger, coupe le croustillant.', '« Les cigares de Lalla partent vite : je vous en mets une portion pour la table avec vos cocktails ? »', 60, true, null, '2026-11-16T17:25:45.604315+00:00'),
('552bf460-6bfb-4115-8926-a75d384a9205', 'baro', 'entree', 'Toast de bœuf chimichurri', 'Le Jimi Hendrix rend hommage au musicien, tombé sous le charme du Maroc dans les années 60.', 'Jimi Hendrix', 'Côtes du Rhône Guigal', 'Le chimichurri est fait d''herbes vertes : le cocktail reprend basilic, thym et origan ; le Rhône apporte le fruit noir pour le bœuf.', '« Le toast est piquant et plein d''herbes : le Jimi Hendrix a exactement les mêmes. »', 70, true, null, '2026-11-16T17:25:45.604315+00:00'),
('1153f5db-b787-45e6-9eee-f9f0b13b54e4', 'baro', 'entree', 'Daurade façon ceviche', 'Le ceviche vient du Pérou ; ici il rencontre la mangue et le wonton croustillant.', 'Lust Martini', 'Touraine Sauvignon Blanc', 'La mangue du ceviche se retrouve dans le cocktail ; le Sauvignon, vif, prolonge le citron de la marinade.', '« Un plat frais et un peu piquant : avec le Lust Martini, c''est la mangue des deux côtés. »', 80, true, null, '2026-11-16T17:25:45.604315+00:00'),
('8d63bdf2-2704-4eb7-a243-49349a8b603c', 'baro', 'entree', 'Carpaccio de bœuf', 'Le carpaccio est né au Harry''s Bar de Venise, le Negroni à Florence.', 'Negroni Fizz', 'Chianti', 'L''amertume et la fraise du Negroni Fizz réveillent le bœuf cru ; le Chianti a l''acidité qui va avec le parmesan.', '« Un plat italien, un vin toscan : le Chianti, tout simplement. »', 90, true, null, '2026-11-16T17:25:45.604315+00:00'),
('9affd6ea-8009-4c5f-9e94-30fbeb82628a', 'baro', 'entree', 'Brie pané et poire', 'Le Mooja, « la vague » : un tourbillon entre parfum de fleur et fruit exotique.', 'Mooja', 'Studio by Miraval rosé', 'Le fondant et la poire aiment le fruité et la fleur d''oranger du Mooja ; le rosé reste frais face au fromage chaud.', '« Pour le brie, un cocktail doux et floral : le Mooja. »', 100, true, null, '2026-11-16T17:25:45.604315+00:00'),
('3da9a490-0a48-4cf4-a547-a04166a41044', 'baro', 'dessert', 'Tarte chocolat et entremets noisette', 'Pâte d''amande, crémeux mangue-passion, caramel, et un entremets croustillant aux noisettes.', 'Martini Espresso', 'Amaretto (digestif)', 'Le café et le chocolat se renforcent ; l''amande de l''Amaretto répond à la pâte d''amande et à la noisette.', '« Pour finir, un Martini Espresso avec le chocolat ? C''est le dessert et le café en un. »', 110, true, null, '2026-11-16T17:25:45.604315+00:00'),
('c8b4f41a-3aab-4f94-b6c5-20f2d1ff2ba2', 'baro', 'entree', 'Duo de mini burgers', 'Deux burgers en format bouchée, pensés pour l''apéritif à partager.', 'Old Fashioned', 'Médaillon', 'Le gras et le grillé demandent de la structure ; le Médaillon, assemblage Cabernet, Merlot et Syrah, a les tanins qu''il faut.', '« Ils partent en deux bouchées : je vous en mets un duo par personne ? »', 300, true, null, '2026-11-16T17:32:42.908254+00:00'),
('1974dd5a-c3ac-4294-ab5a-e07a175a8e69', 'baro', 'entree', 'Duo de beignets de poulpe', 'Le poulpe de nos côtes atlantiques, servi en beignet comme dans les ports.', 'Apérol Spritz', 'Ait Souala Gris', 'La friture aime les bulles et l''amertume qui nettoient la bouche ; le gris marocain reste frais et léger.', '« Avec un Spritz, c''est l''apéro du bord de mer. »', 305, true, null, '2026-11-16T17:32:42.908254+00:00'),
('80778519-aeec-4f1c-bde5-3c49b715a7ba', 'baro', 'entree', 'Pétales d''avocat aux gambas', 'Un plat frais et léger, avec quinoa, pour ceux qui veulent garder de la place.', 'Botanic Gin Tonic', 'Pinot Grigio', 'L''avocat est crémeux, les gambas iodées ; les herbes et le poivre du gin tonic les réveillent, le Pinot Grigio reste discret.', '« Si vous cherchez frais et léger, c''est celui-là, avec un Botanic Gin Tonic. »', 310, true, null, '2026-11-16T17:32:42.908254+00:00'),
('e775614e-9d51-440b-8809-ccd7beea785c', 'baro', 'entree', 'Burrata, tomate et pesto', 'La burrata, une mozzarella qui cache un cœur de crème.', 'Negroni', 'La Vieille Ferme rosé', 'Tomate et pesto sont italiens comme le Negroni, dont l''amertume coupe la crème ; le rosé du Rhône apporte le fruit.', '« Une burrata à partager pour commencer ? Avec un Negroni, c''est l''Italie. »', 315, true, null, '2026-11-16T17:32:42.908254+00:00'),
('edcceed9-0576-44fd-9aa2-b3f477cebda9', 'baro', 'entree', 'Olives, tapenade à la truffe', 'Nos olives marocaines ; notre huile vient d''oliviers centenaires à Tassoultante, près de Marrakech.', 'Dry Martini (dirty)', 'Flûte de Prosecco', 'L''olive est née pour le Martini ; les bulles légères ouvrent l''appétit sans couvrir la truffe.', '« Pour patienter, les olives à la truffe et un Dirty Martini ? »', 320, true, null, '2026-11-16T17:32:42.908254+00:00'),
('17d4a416-e6ba-4614-ad01-51400b4a6d94', 'baro', 'entree', 'Houmous betterave à la feta', 'Le houmous libanais, peint en rose par la betterave.', 'Mojito Especial', 'Verre de Grenache', 'La betterave est douce et terreuse ; la menthe et la citronnelle du Mojito la rafraîchissent, le rosé reprend son fruit.', '« Le houmous rose pour la table : tout le monde y trempe son pain. »', 325, true, null, '2026-11-16T17:32:42.908254+00:00'),
('f63173f4-dcb9-4004-a156-f1f9c799e7f0', 'baro', 'entree', 'Cromesquis de tanjia', 'La tanjia, cuite toute la nuit dans les cendres du hammam, roulée ici en bouchée croustillante au citron confit.', 'Churchill', 'CB Signature', 'La tanjia est épicée et fondante ; le safran, la cannelle et le pruneau du Churchill lui répondent.', '« C''est la tanjia de Marrakech en bouchée : un Churchill avec, il a les mêmes épices. »', 330, true, null, '2026-11-16T17:32:42.908254+00:00'),
('050b79fe-471d-4b21-8c3e-e1079944a04c', 'baro', 'entree', 'Marrakesh 5AM', 'Le sandwich qu''on mange au petit matin dans les rues de Marrakech, quand la ville s''endort.', 'Naughty Tequila', 'Verre de Merlot', 'Viande hachée, tomate et oignon appellent du piquant ; la harissa du cocktail fait le lien, le Merlot reste souple.', '« Le sandwich de 5 heures du matin, mais ce soir : avec une Naughty Tequila, pour ceux qui aiment le piquant. »', 335, true, null, '2026-11-16T17:32:42.908254+00:00'),
('4433547e-dfe3-4571-a0ae-83cc45a1c785', 'baro', 'entree', 'Calamars frits à la tektouka', 'La tektouka, salade cuite de poivrons et tomates, star des tables marocaines.', 'Paloma', 'Touraine Sauvignon Blanc', 'Le pamplemousse de la Paloma coupe la friture ; le Sauvignon, vif, va avec la tektouka de poivrons.', '« Des calamars pour la table ? Avec une Paloma, c''est frais et croquant. »', 340, true, null, '2026-11-16T17:32:42.908254+00:00'),
('68a11b19-286f-426c-aebf-553d51fe3ef3', 'baro', 'entree', 'Sardines marocaines épicées', 'Le Maroc est le premier producteur mondial de sardines.', 'Margarita', 'Ait Souala Gris', 'Le sel et le citron de la Margarita coupent le gras de la sardine ; un gris marocain avec un poisson marocain.', '« Le Maroc est le pays de la sardine : goûtez-les épicées, avec une Margarita. »', 345, true, null, '2026-11-16T17:32:42.908254+00:00'),
('2cee9e27-c868-4fa5-a8d9-1d0562fc8b53', 'baro', 'entree', 'Cigars aux trois fromages', 'La feuille de brick roulée à la main, façon briouate.', 'Amaretto Sour', 'Roslane 1er Cru blanc', 'Le fromage chaud aime le sucré-acide de l''Amaretto Sour ; le Chardonnay est rond comme le fromage fondu.', '« Les cigars aux fromages et un Amaretto Sour : le sucré-salé qui marche toujours. »', 350, true, null, '2026-11-16T17:32:42.908254+00:00'),
('a972d4d4-1479-4aac-8867-73e86b23d448', 'baro', 'entree', 'À travers le Maroc', 'Un tour du Maroc en quatre salades à partager.', 'Moscow Mule', 'Ait Souala Gris', 'Quatre salades, quatre goûts ; le gingembre et le citron vert du Moscow Mule les accompagnent toutes, comme le gris.', '« Pour découvrir le Maroc en une fois : les quatre salades à partager. »', 355, true, null, '2026-11-16T17:32:42.908254+00:00'),
('d6d5df79-2108-48b5-a437-b6d4b3bbc85f', 'baro', 'dessert', 'Panna cotta du moment', 'Une panna cotta aux saveurs de la saison.', 'Rosée du Matin', 'Perrier-Jouët Blason Rosé', 'Un dessert léger demande un verre léger ; la rose et la camomille restent dans la douceur.', '« Un dessert léger pour finir, avec une coupe de rosé ? »', 360, true, null, '2026-11-16T17:32:42.908254+00:00'),
('074dec68-162f-4be0-a37c-05c03db65562', 'zz', 'entree', 'Tanjia Marrakchia', 'La tanjia est le plat de Marrakech cuit toute une nuit dans les cendres du hammam ; ici, elle devient croustillante.', 'Marrakesh Market', 'Côtes du Rhône Guigal', 'Le jarret confit au safran aime les épices chaudes du cocktail ; le Rhône a la rondeur d''une viande mijotée.', '« C''est le plat le plus marrakchi de la carte. Avec un Marrakesh Market, vous avez la médina dans l''assiette et dans le verre. »', 120, true, null, '2026-11-16T17:25:45.604315+00:00'),
('3564a42d-848a-4bf4-bb73-9119cd677786', 'zz', 'entree', 'Burrata Beldi', '« Beldi » veut dire « de chez nous » : une burrata relevée par la mélasse de grenade du Levant.', 'Tomatini', 'Studio by Miraval rosé', 'Le Tomatini reprend la tomate, l''origan et la note fromagère ; le rosé reste frais face à la crème de la burrata.', '« Pour ouvrir, la burrata et un Tomatini : une salade de tomates dans un verre, en plus surprenant. »', 130, true, null, '2026-11-16T17:25:45.604315+00:00'),
('ca7c1336-0402-4a30-a132-81f9330cdfff', 'zz', 'entree', 'Gambas de Carthage', 'Carthage, port de Tunisie, patrie de la harissa.', 'Mojito Soltane', 'Petit Chablis', 'La harissa chauffe, la menthe et le prosecco rafraîchissent ; le Chablis, minéral, tient tête au beurre citronné.', '« Les gambas sont relevées : un Mojito Soltane pour les calmer, ou un Petit Chablis bien frais. »', 140, true, null, '2026-11-16T17:25:45.604315+00:00'),
('06d06646-29ed-43c3-9fab-9162408bc941', 'zz', 'entree', 'Ceviche Barba', 'La marinade berbère à la coriandre rencontre le ceviche d''Amérique du Sud.', 'Rose de Damas', 'Touraine Sauvignon Blanc', 'L''hibiscus et la rose rejoignent la douceur de la betterave ; le Sauvignon prolonge la coriandre et le citron.', '« Un plat frais et très coloré : la Rose de Damas a la même couleur, et la même légèreté. »', 150, true, null, '2026-11-16T17:25:45.604315+00:00'),
('8ac34d42-9b5f-4a8b-ac74-2d60ec699a80', 'zz', 'entree', 'Tfaya chèvre chaud', 'La tfaya est la garniture des grands couscous de fête, oignons confits à la cannelle.', 'Berberliner', 'Ait Souala Viognier', 'Oignons à la cannelle, amlou et miel d''amande parlent le même sucré-salé ; le Viognier adoucit le chèvre.', '« Le chèvre avec la tfaya des couscous de fête : avec le Berberliner à l''amlou, c''est un goûter de grand-mère revisité. »', 160, true, null, '2026-11-16T17:25:45.604315+00:00'),
('c0779680-495b-4c99-872c-ca335847d3f5', 'zz', 'entree', 'Kefta Meshwya', 'Le CB Signature est la cuvée de la maison.', 'Scorpion', 'CB Signature', 'Le grillé et le poivron fumé répondent aux poivrons et à la harissa du Scorpion ; le CB Signature a le fruit pour la viande grillée.', '« Pour les grillades, notre propre vin, le CB Signature. »', 170, true, null, '2026-11-16T17:25:45.604315+00:00'),
('c42e3db5-50bb-42a0-b6c5-fa20925672ce', 'zz', 'plat', 'Perles du Maghreb', 'La mhamssa, perles de blé roulées à la main, cuisinée comme un risotto.', 'NoorShems', 'Chassagne-Montrachet', 'La crème de safran et les palourdes appellent un blanc riche ; le NoorShems est infusé au même safran.', '« Les perles de blé au safran : le NoorShems est le cocktail du safran, ils sont faits l''un pour l''autre. »', 180, true, null, '2026-11-16T17:25:45.604315+00:00'),
('a8c71149-c0e7-4cfc-b7dc-b1b20d30af30', 'zz', 'plat', 'Le Tigre qui Danse', 'Le tigre danse et le serpent danse : les deux danseurs de la maison réunis.', 'Snake Dance', 'S de Siroua (Syrah)', 'Gingembre et ras el hanout dans le plat, gingembre et vanille pimentée dans le verre ; la Syrah est poivrée comme la sauce.', '« Le Tigre qui Danse avec un Snake Dance : nos deux danseurs. »', 190, true, null, '2026-11-16T17:25:45.604315+00:00'),
('8cb7400b-733c-46eb-9521-72333553f233', 'zz', 'plat', 'Osso Bucco Mrozia', 'La mrozia est le plat de l''Aïd, sucré-salé aux sept épices.', 'Old Fashioned', 'Marqués de Cáceres Reserva', 'La viande longuement cuite demande des tanins fondus ; le whisky répond au caramel du jus réduit.', '« Pour la viande, un Rioja : il est généreux avec les épices. »', 200, true, null, '2026-11-16T17:25:45.604315+00:00'),
('52c0d687-c40b-4159-acb9-d9a93fae3e57', 'zz', 'plat', 'Agneau Samarkand', 'Samarkand, l''étape de la route de la soie.', 'Mezcal Negroni', 'Château Le Vieux Fort', 'Le beurre noisette et les câpres aiment un Bordeaux souple ; le fumé du mezcal répond à la côtelette grillée.', '« Avec l''agneau, un Bordeaux : le Château Le Vieux Fort. »', 210, true, null, '2026-11-16T17:25:45.604315+00:00'),
('118b1551-2a15-47fe-9333-7dad6afc51a8', 'zz', 'plat', 'Loup Bar doré', 'La chermoula est la marinade de tous les poissons du Maroc, d''Essaouira à Tétouan.', 'Cardarita', 'Ait Souala Gris', 'La chermoula est herbacée et citronnée comme le céleri et la cardamome du Cardarita ; un gris marocain est le vin naturel du tajine de poisson.', '« Avec le tajine de poisson, un gris marocain : c''est l''accord de chez nous. »', 220, true, null, '2026-11-16T17:25:45.604315+00:00'),
('e019119d-9bbc-4614-ad86-6019f7352cb4', 'zz', 'dessert', 'Fondant Amlou', 'Les dattes et l''amande : les deux douceurs du Maroc.', 'Dolce Hayat', 'Perrier-Jouët Blason Rosé', 'Les dattes du Dolce Hayat et l''amande de l''amlou se répondent ; les bulles allègent un dessert riche.', '« On fête quelque chose ce soir ? Le Fondant Amlou avec deux coupes de rosé. »', 230, true, null, '2026-11-16T17:25:45.604315+00:00'),
('2aa42951-7d4b-4292-8a32-5dbcc79d1cc6', 'zz', 'entree', 'Houmous Fatteh', 'La fatteh, le plat syrien et libanais où l''on brise le pain grillé sur le houmous.', 'Basil Smash', 'Ait Souala Gris', 'Le basilic et le citron allègent le sésame du houmous ; le gris reste frais face au croquant de la pita.', '« Le houmous à la libanaise, avec ses éclats de pita : parfait pour commencer à plusieurs. »', 400, true, null, '2026-11-16T17:32:42.908254+00:00'),
('dd2a58c1-8043-46df-a4ec-59600b040eb5', 'zz', 'entree', 'Shawarmas Mezze', 'La Khamsa, la main de Fatma qui protège et porte chance.', 'Khamsa Colada', 'Pinot Grigio', 'L''ananas et l''orgeat du Khamsa Colada adoucissent le saté et l''oignon mariné ; le Pinot Grigio reste léger.', '« Les shawarmas en mezze, à partager, avec un Khamsa Colada pour la douceur. »', 405, true, null, '2026-11-16T17:32:42.908254+00:00'),
('f916fa6f-6c90-4422-b4e9-41c73a42e591', 'zz', 'entree', 'Daghmira Parmentier', 'La daghmira, poulet aux oignons confits de la cuisine marrakchie, ici en parmentier.', 'Whisky Sour', 'Bourgogne Pinot Noir', 'Le poulet mijoté aux oignons est fondant et sucré ; le Pinot Noir, fin et fruité, ne l''écrase pas.', '« C''est le plat réconfort de la carte : avec un Pinot Noir, c''est le dimanche en famille. »', 410, true, null, '2026-11-16T17:32:42.908254+00:00'),
('2b6fd9f7-e8e5-4c96-8377-90208ec15cc2', 'zz', 'entree', 'Cannelloni Tribal', 'Le trid, ancêtre de la pastilla, feuilles fines roulées à la main.', 'Amaretto Sour', 'Ait Souala Viognier', 'Le bouillon au safran aime l''abricot du Viognier ; l''amande de l''Amaretto rappelle les fêtes.', '« Le trid, c''est l''ancêtre de la pastilla : on l''a roulé en cannelloni. »', 415, true, null, '2026-11-16T17:32:42.908254+00:00'),
('7a5980c6-3579-4758-94bf-816823d4011c', 'zz', 'entree', 'Salade Zamalek', 'Zamalek, l''île chic du Caire, au milieu du Nil.', 'Passion Martini', 'Touraine Sauvignon Blanc', 'La mangue de la salade rencontre le fruit de la passion ; le Sauvignon, vif, allège l''avocat.', '« Une salade complète et fruitée : avec un Passion Martini, c''est un vrai repas léger. »', 420, true, null, '2026-11-16T17:32:42.908254+00:00'),
('59509f08-6087-4583-b537-2a23b12c8897', 'zz', 'entree', 'Rivages d''Oman', 'Oman, port des marchands d''épices sur la route de l''Orient.', 'Margarita', 'Petit Chablis', 'Le crabe est doux et iodé ; le sel et le citron de la Margarita le relancent, le Chablis minéral reste dans la mer.', '« L''araignée de mer au paprika : un Petit Chablis bien frais et c''est parfait. »', 425, true, null, '2026-11-16T17:32:42.908254+00:00'),
('168e88dd-c055-42f8-ace5-2919eb467935', 'zz', 'entree', 'Briouates Thalata', '« Thalata » veut dire trois : trois fromages, une seule bouchée.', 'Apérol Spritz', 'Studio by Miraval rosé', 'Trois fromages fondants dans la brick ; les bulles et l''amertume du Spritz coupent le gras.', '« Les briouates aux trois fromages partent vite, une portion pour la table ? »', 430, true, null, '2026-11-16T17:32:42.908254+00:00'),
('7a8f78e7-6dd3-4e81-9607-006170e83abe', 'zz', 'entree', 'Falafels Tarator', 'Le tarator, sauce au tahiné et citron des cuisines du Levant.', 'Moscow Mule', 'Verre de Grenache', 'Le gingembre et le citron vert allègent les pois chiches frits et la sauce au tahiné.', '« Les falafels, c''est la bouchée végétarienne qui plaît à tout le monde. »', 435, true, null, '2026-11-16T17:32:42.908254+00:00'),
('6d526e57-681d-441f-bb9d-0952b45ef3aa', 'zz', 'entree', 'Poulpe Levantin', 'Le Levant, côte est de la Méditerranée, du Liban à la Syrie.', 'Negroni', 'La Vieille Ferme rosé', 'La sauce aigre-douce relevée appelle l''amertume du Negroni ; le rosé du Rhône a le fruit pour la croquette.', '« Le poulpe en croquette, un peu piquant : un Negroni avec, ça se marie très bien. »', 440, true, null, '2026-11-16T17:32:42.908254+00:00'),
('cf3ce433-4032-4957-9ce3-8467c1af1811', 'zz', 'entree', 'Marrakesh-Beyrouth', 'Deux villes, deux cuisines, une seule assiette.', 'Mojito Soltane', 'Pinot Grigio', 'Baba ghanouj, taboulé et légumes acidulés sont frais et herbacés, comme la menthe et le géranium du Mojito Soltane.', '« Le meilleur des deux villes en une assiette, à partager pour commencer. »', 445, true, null, '2026-11-16T17:32:42.908254+00:00'),
('fb9daa1f-88d3-4d33-9a77-886f482cdcac', 'zz', 'plat', 'Tawouk', 'Le tawouk, brochette de poulet de Beyrouth, servie avec la toum, sa sauce à l''ail.', 'Snake Dance', 'Ait Souala Viognier', 'Le riz au curry aime le gingembre et la vanille pimentée ; le Viognier est l''accord classique des plats au curry.', '« Le tawouk avec un Snake Dance : le gingembre répond au curry. »', 450, true, null, '2026-11-16T17:32:42.908254+00:00'),
('e355648b-253c-45a8-ab6e-24b1d9018064', 'zz', 'dessert', 'Crème brûlée à la verveine', 'La verveine, l''herbe du thé du soir dans les maisons marocaines.', 'Mojito Soltane', 'Flûte de Prosecco', 'La verveine est herbacée comme la menthe ; les bulles légères accompagnent la crème.', '« La crème brûlée à la verveine, c''est le thé du soir en dessert. »', 455, true, null, '2026-11-16T17:32:42.908254+00:00'),
('662ad47c-1f17-4066-9040-ebeb5cfdb816', 'zz', 'dessert', 'Tiramisu au café Arabica', 'Mascarpone et biscuit imbibé de café parfumé aux épices.', 'Martini Espresso', 'Amaretto (digestif)', 'Café contre café ; l''Amaretto est la liqueur que l''on met souvent dans le tiramisu.', '« Un tiramisu avec un Martini Espresso, c''est le dessert et le café en un. »', 460, true, null, '2026-11-16T17:32:42.908254+00:00'),
('5a752645-2f3f-4409-a952-ff9604e34fc9', 'zz', 'dessert', 'Panna cotta orientale', 'Au thé vert, avec un coulis d''hibiscus.', 'Rose de Damas', 'Perrier-Jouët Blason Rosé', 'L''hibiscus du coulis et celui du cocktail se répondent ; le thé vert reste léger.', '« La panna cotta au thé vert et hibiscus, avec la Rose de Damas : la même fleur dans l''assiette et dans le verre. »', 465, true, null, '2026-11-16T17:32:42.908254+00:00')
